(function(){var m=window.SITE_DATA_BY_DOMAIN||{};var d=m["audio"]||{};var a=d["algorithms"]||[];for(var i=0;i<a.length;i++){if(a[i].id=="alg-mx-fp8-codec"){a[i]["long_html"]="<nav class=\"long-toc\"><b>本页目录</b><ol><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-1\">一 · 从一次流式首包超时说起</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-2\">二 · 机制：32 元素块与 E8M0 共享缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-3\">三 · 它不解决什么：三条硬边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-4\">四 · 与 per-tensor FP8 的差别：粒度即精度</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-5\">五 · 适用边界的判定顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-6\">六 · 事故复盘落到机制上</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-7\">七 · 块缩放救不了的那一类层：MXFP8 的失效面与代价账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-8\">八 · 权重侧：离线分块与 E8M0 因子的生成</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-9\">九 · 激活侧：逐 token 分块与在线因子</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-10\">十 · Tensor Core 主循环：操作数读取与累加后统一缩放</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-11\">十一 · 敏感层旁路：RVQ 码本与输出层保留 BF16</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-12\">十二 · 混合精度栈的层间编排与 batch 依赖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-13\">十三 · 边界条件：块粒度与 batch 摊薄决定 MXFP8 能否落地</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-14\">十四 · 缩放因子的取整与误差上界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-15\">十五 · 累加后统一应用缩放因子的推导</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-16\">十六 · 分块与量化的可实现伪代码</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-17\">十七 · 通道补齐的代价模型</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-18\">十八 · 混合精度栈的敏感度判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-19\">十九 · 块缩放的三条边界：何时 MXFP8 反而更慢、更不准</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-20\">二十 · 请求形态：MXFP8 只在大块前向里兑现吞吐</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-21\">二十一 · 长度分布：短序列堆块、长序列摊块</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-22\">二十二 · 并发与批大小：收益曲线的拐点</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-23\">二十三 · 负载不对时的三种失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-24\">二十四 · 配方落地：按负载分档的精度栈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-25\">二十五 · 负载配方：块缩放收益在哪种请求形态下成立</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-26\">二十六 · 硬件档位与并行拓扑的耦合</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-27\">二十七 · 量化方案的混合精度栈</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-28\">二十八 · KV 策略与块缩放的交互</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-29\">二十九 · 调度参数与批处理形态</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-30\">三十 · 可复现的配置思路</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-31\">三十一 · 边界条件：这套配方在什么负载下会失效</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-32\">三十二 · 敏感层清单与混合精度栈的落地判据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-33\">三十三 · 显存与带宽：块缩放元数据把收益吃掉的那一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-34\">三十四 · 通信：块缩放因子在集合通信里的放大效应</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-35\">三十五 · 功耗与吞吐：小 batch 是 MXFP8 的收益悬崖</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-36\">三十六 · 尾延迟：块边界与补齐通道制造的抖动源</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-37\">三十七 · 规模上去以后哪里先崩：一条代价排序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-38\">三十八 · 规模上去以后，先崩的是元数据带宽而不是算力</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-39\">三十九 · 小 batch 与尾延迟：因子解码摊不薄的那一段</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-40\">四十 · 通信与功耗：压缩率换来的是另一种账</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-41\">四十一 · 精度失败的三种指纹与定位顺序</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-42\">四十二 · OOM 的真实来源：元数据、补齐与 KV 之外的第三块显存</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-43\">四十三 · 批抖动与路由不均：小 batch 下收益被抵消的量化证据</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-44\">四十四 · 尾延迟尖刺：块统计的同步点与补齐的边界计算</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-45\">四十五 · 监控面与回滚梯度：从混合精度栈逐级降级</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-46\">四十六 · 失效边界：块缩放的三类代价与可观测信号</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-47\">四十七 · 对照维度：先分清&quot;缩放粒度&quot;与&quot;数据通路&quot;</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-48\">四十八 · 决策表：把适用条件写成可执行的门槛</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-49\">四十九 · 与 per-tensor FP8 的分界：离群值分布决定一切</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-50\">五十 · 与 MXINT8 的分工：数值域与敏感度分层</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-51\">五十一 · 与更细粒度量化及 BF16 回退的边界</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-52\">五十二 · 选型收口：三个否决项与一条固化路径</button></li><li><button type=\"button\" class=\"toc-link\" data-sec=\"alg-mx-fp8-codec-sec-53\">五十三 · 同族取舍：MXFP8 与 per-tensor FP8、MXINT8、BF16 的分界</button></li></ol></nav><figure class=\"diagram\" data-fig=\"algo-flow\"><svg style=\"max-width:506px;margin:0 auto\" xmlns=\"http://www.w3.org/2000/svg\" viewBox=\"0 0 505.5 352\" preserveAspectRatio=\"xMidYMid meet\" role=\"img\"><rect x=\"58.0\" y=\"12.0\" width=\"423.5\" height=\"44.8\" rx=\"8\" fill=\"#fdf3e3\" stroke=\"#ecd9b8\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"34.4\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"38.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">1</text><text x=\"75.0\" y=\"39.6\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">把权重与激活按 32 元素分块，统计块内最大绝对值</text><line x1=\"82.0\" y1=\"58.8\" x2=\"82.0\" y2=\"75.8\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 74.8 L 86.5 74.8 L 82.0 82.8 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"82.8\" width=\"423.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"105.3\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"109.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">2</text><text x=\"75.0\" y=\"110.5\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">为每块计算共享 E8M0 缩放因子，块内元素量化为 FP8</text><line x1=\"82.0\" y1=\"129.7\" x2=\"82.0\" y2=\"146.7\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 145.7 L 86.5 145.7 L 82.0 153.7 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"153.7\" width=\"423.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"176.1\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"180.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">3</text><text x=\"75.0\" y=\"181.3\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">推理时 Tensor Core 读 MXFP8 操作数，块缩放因子在累加后…</text><line x1=\"82.0\" y1=\"200.5\" x2=\"82.0\" y2=\"217.5\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 216.5 L 86.5 216.5 L 82.0 224.5 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"224.5\" width=\"423.5\" height=\"44.8\" rx=\"8\" fill=\"#ffffff\" stroke=\"#d8d3c6\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"247.0\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"251.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">4</text><text x=\"75.0\" y=\"252.2\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">对 RVQ 码本与输出层保留 BF16，避免块缩放引入的码本索引偏移</text><line x1=\"82.0\" y1=\"271.4\" x2=\"82.0\" y2=\"288.4\" stroke=\"#d8d3c6\" stroke-width=\"1.4\"/><path d=\"M 77.5 287.4 L 86.5 287.4 L 82.0 295.4 Z\" fill=\"#d8d3c6\"/><rect x=\"58.0\" y=\"295.4\" width=\"423.5\" height=\"44.8\" rx=\"8\" fill=\"#e8f5ec\" stroke=\"#cde9d5\" stroke-width=\"1.2\"/><circle cx=\"26\" cy=\"317.8\" r=\"12\" fill=\"#1f4e79\"/><text x=\"26.0\" y=\"322.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"11.5\" fill=\"#ffffff\" font-weight=\"700\" text-anchor=\"middle\">5</text><text x=\"75.0\" y=\"323.0\" font-family=\"-apple-system,'PingFang SC','Noto Sans SC','Microsoft YaHei',sans-serif\" font-size=\"13.0\" fill=\"#0f1720\" font-weight=\"600\" text-anchor=\"start\">按层敏感度选择 MXFP8 或 MXINT8，形成混合微缩放精度栈</text></svg><figcaption><b>执行流程</b> · 从输入到输出的关键步骤；每一步的复杂度与坑在正文展开。</figcaption></figure>\n<h3 id=\"alg-mx-fp8-codec-sec-1\">一 · 从一次流式首包超时说起</h3>\n<p>某条流式 TTS 服务在 B200 上把编解码器与声学模型的线性层从 BF16 切到 per-tensor FP8，离线音频编码批的吞吐确实抬上去了，但线上出现两类故障：一是长句尾部的音素错位，二是首包延迟不降反升。前者是精度问题——声学模型某层激活里存在少量离群值，整张量共享一个缩放因子时，这些离群值把其余元素的有效位压缩掉，编解码器输出的隐状态发生偏移，RVQ 码本索引跟着漂移，合成音频出现音素错位或音质突变。后者是系统问题——首包阶段 batch 极小，per-tensor FP8 的量化/反量化路径与 kernel 启动开销无法被摊薄，端到端延迟反而劣于 BF16。</p>\n<p>这次事故暴露的正是 MXFP8 要解决的具体推理问题：<strong>编解码器与声学模型在 FP8 下动态范围不足，整张量缩放会因局部离群值牺牲精度，使 Blackwell 上 FP8 提速难以安全落地。</strong>它不解决“模型本身算不动”的问题，也不解决“batch 调度不合理”的问题——那些属于算子选型与批调度条目。它只把量化粒度从张量级降到 32 元素块级，用块内共享缩放吸收离群值，让一个极端值不再拖垮整张权重或激活的表示精度。</p>\n<p>代价必须前置说清：块缩放因子带来额外元数据与解码开销，小 batch 下收益被抵消；编解码器卷积层通道数不总是 32 的倍数，需补齐或退化为 per-channel 量化。这两条决定了 MXFP8 的适用边界，也是本部分要划清的线。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-2\">二 · 机制：32 元素块与 E8M0 共享缩放</h3>\n<p>按数据流顺序，MXFP8 的编解码路径是：权重与激活先按 32 元素分块，统计块内最大绝对值；据此为每块计算共享 E8M0 缩放因子；块内元素量化为 FP8；推理时 Tensor Core 直接读 MXFP8 操作数，块缩放因子在累加完成后统一应用，恢复数值尺度。核心公式为</p>\n<div class=\"formula\">$$x_i \\approx s_b \\cdot q_i,\\quad s_b = \\frac{\\max_{j\\in b}|x_j|}{\\mathrm{FP8}_{\\max}}$$</div>\n<p>其中 $b$ 为 32 元素块，$s_b$ 为共享 E8M0 缩放因子，$q_i$ 为块内 FP8 量化值。缩放因子只随块变化，故元数据量为每 32 元素一个字节量级——这是 MXFP8 全部额外开销的来源，也是它相对 per-tensor FP8 多出来的那部分带宽。</p>\n<p>误差上界可写成 $\\text{err} \\le \\frac{s}{2}\\sqrt{32}$ 的量级：块内 32 个元素的量化误差按共享缩放 $s$ 放大，块越大、块内动态范围越宽，上界越松。这正是 32 这个数字的工程含义——块足够小以保住局部动态范围，又足够大以让元数据摊薄。E8M0 只存指数不存尾数，使缩放因子本身几乎不占精度预算，代价是缩放只能取 2 的幂，块内最大值与 FP8 上限之间的余量必须由块内元素自己吸收。</p>\n<p>系统代价落在三处：权重显存与带宽因 FP8 表示而压缩，这是收益；每 32 元素一字节的缩放元数据要随操作数一起搬进 SMEM/TMEM 并在累加后解码，这是带宽与指令开销；块边界要求张量最后一维能被 32 整除，否则补齐引入无效计算与边界误差。以一层 $4096\\times4096$ 的声学模型线性层为例，权重按 32 元素分块后缩放因子数量为 $4096\\times4096/32$，每个因子一字节量级，相对 BF16 权重是零头，但相对纯 FP8 权重就是实打实的额外流量——batch 越小，这笔流量占总带宽的比例越高。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-3\">三 · 它不解决什么：三条硬边界</h3>\n<p>第一条边界是<strong>小 batch 流式首包</strong>。MXFP8 的吞吐优势来自 Tensor Core 对 MX 操作数的原生读取，但块缩放因子的元数据读取与解码是固定开销，batch 越大越易摊薄。首包场景 batch 常为个位数，这笔开销无法摊薄，MXFP8 吞吐可能低于预期甚至不如 BF16 路径。此时正确的工程判断不是“再调调块大小”，而是首包阶段走 BF16 或 per-channel 量化路径，等 batch 起来再切 MXFP8——精度栈按请求形态分段，而不是全服务统一。</p>\n<p>第二条边界是<strong>通道数不规整的卷积层</strong>。编解码器卷积层通道数不总是 32 的倍数，补齐会引入无效计算与边界误差，退化为 per-channel 量化又丢失块级动态范围优势。这是一个二选一的退化决策：补齐适合通道数接近 32 倍数、且补齐比例低的层；per-channel 适合通道数远离 32 倍数、且该层对动态范围不敏感的层。两者都不如原生 32 对齐，所以层维度能否被 32 整除或可低成本补齐，是 MXFP8 能否上这条层的先决条件。</p>\n<p>第三条边界是<strong>码本与输出层</strong>。对 RVQ 码本与输出层误用块缩放量化，会因缩放因子扰动导致码本索引偏移，合成音频出现音素错位或音质突变。这类层的输出直接决定离散索引，任何尺度扰动都会被索引映射放大，因此 RVQ 码本与输出层保留 BF16 不是保守，而是正确性要求。MXFP8 的适用范围是隐状态与线性层的大 batch 前向，不是整网无差别替换。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-4\">四 · 与 per-tensor FP8 的差别：粒度即精度</h3>\n<p>差别只在缩放粒度，但后果是精度与吞吐的双重分野。per-tensor FP8 用单一缩放覆盖整张量，离群值会压缩其余元素的有效位；MXFP8 每 32 元素独立缩放，局部动态范围得以保留，精度损失小于 per-tensor FP8，同时吞吐接近 INT8。用一张表把三条路径的工程取舍摆清楚：</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>缩放粒度</th><th>离群值影响</th><th>元数据开销</th><th>适用形态</th></tr></thead><tbody>\n<tr><td>per-tensor FP8</td><td>整张量一个缩放</td><td>全局压缩有效位</td><td>可忽略</td><td>动态范围平稳的层</td></tr>\n<tr><td>MXFP8</td><td>32 元素共享 E8M0</td><td>局限在块内</td><td>每 32 元素一字节量级</td><td>大 batch 卷积/线性前向</td></tr>\n<tr><td>MXINT8</td><td>32 元素共享缩放</td><td>局限在块内，整数格点</td><td>同上</td><td>敏感度较低的层</td></tr>\n</tbody></table>\n<p>注意 MXINT8 与 MXFP8 共享同一套块缩放框架，区别在块内元素用整数还是浮点表示。按层敏感度在两者间选择，形成混合微缩放精度栈：对数值分布接近均匀、对尾数不敏感的层用 MXINT8，对需要浮点尾数保精度的层用 MXFP8，对码本与输出层保留 BF16。这个栈的调度单位是层，不是张量，也不是整网——层敏感度是编译期或校准期确定的静态属性，运行时不再切换。</p>\n<p>系统代价上，MXFP8 相对 per-tensor FP8 多出的就是元数据带宽与解码指令；相对 BF16 省下的是权重显存与权重带宽。收益能否兑现，取决于这笔元数据开销能否被 batch 摊薄，以及层维度是否 32 对齐。两个条件同时成立时，MXFP8 是 Blackwell 上安全使用 FP8 提速的可行路径；任一条件不成立，退化路径比强行 MXFP8 更稳。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-5\">五 · 适用边界的判定顺序</h3>\n<p>把边界写成可执行的判定顺序，比记一条“适合大 batch”有用得多。对每一层依次问四个问题：</p>\n<ul>\n<li>该层输出是否直接映射为离散索引（RVQ 码本、输出层）？是则保留 BF16，不再往下问。</li>\n<li>该层最后一维能否被 32 整除，或补齐比例是否足够低？否则退化为 per-channel 量化，或改量化粒度。</li>\n<li>该层在目标请求形态下的 batch 是否足以摊薄每 32 元素一字节的元数据？首包与小 batch 场景先走 BF16 路径。</li>\n<li>该层数值分布是否需要浮点尾数？否则选 MXINT8 而非 MXFP8。</li>\n</ul>\n<p>四个问题都通过，才把该层放进 MXFP8 集合。这个顺序的价值在于它把“精度”与“系统”两类约束交织在一起判定：前两问是正确性与形状约束，后两问是吞吐与数值约束。以流式 TTS 的 chunk 批量为例，chunk 批量使解码器线性层的 batch 足够大，元数据被摊薄，MXFP8 收益兑现；而首包阶段的同一层 batch 极小，判定顺序会在第三问把它挡回 BF16。同一层在不同请求形态下走不同精度路径，这不是不一致，而是精度栈按 SLO 分段。</p>\n<p>规模上限受块缩放元数据带宽与解码开销约束：层数越多、batch 越小，元数据占总流量的比例越高，MXFP8 相对 BF16 的净收益越薄。因此容量规划时不能只按“FP8 权重显存减半”估算，要把元数据流量与解码指令周期计入单请求成本。这条约束与显存、KV cache 条目的结论方向一致：量化省下的是显存与权重带宽，换来的可能是激活侧的元数据开销，两者要在同一张账上算。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-6\">六 · 事故复盘落到机制上</h3>\n<p>回到开头那次事故：音素错位的根因是对 RVQ 码本与输出层误用了块缩放量化，缩放因子扰动被索引映射放大；首包超时的根因是小 batch 下元数据与解码开销无法摊薄。两个根因对应本部分划出的两条边界，修复动作也就明确了——码本与输出层回 BF16，首包阶段回 BF16 或 per-channel，大 batch 前向保留 MXFP8。修复后精度与延迟同时回到 SLO 内，而吞吐收益仍在大 batch 路径上兑现。</p>\n<p>这次复盘给出的工程判断是：MXFP8 不是一个可以整网打开的开关，而是一套按层、按请求形态分段的精度栈。它的机制核心是 32 元素块共享 E8M0 缩放，把离群值的影响关在块内；它的代价核心是每 32 元素一字节量级的元数据与解码开销；它的边界核心是 32 对齐与小 batch 摊薄。三者共同决定了它在 Blackwell 推理栈里的位置——在层维度规整、batch 足够大的前向上替代 per-tensor FP8，在码本、输出层与首包路径上让位给 BF16。任何把 MXFP8 当作全局默认精度的部署，都会在这三条边界上付出代价。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-7\">七 · 块缩放救不了的那一类层：MXFP8 的失效面与代价账</h3>\n<p>一次流式 TTS 服务的回归定位很典型：编解码器卷积与声学模型线性层统一切到 per-tensor FP8 后，离线大 batch 吞吐达标，但线上首包延迟反而抖动，合成音频出现音素错位。根因不在算力，而在缩放粒度——整张量共用一个缩放因子时，某个通道的局部离群值会把其余元素的有效位压掉，量化误差按块内元素数累积，上界可写成 <span class=\"formula\">$$\\text{err}\\le \\frac{s}{2}\\sqrt{32},\\quad s=2^{\\lfloor \\log_2 \\max_j |x_j| \\rfloor}$$</span> 离群值抬升 $s$，误差随 $\\sqrt{32}$ 放大到整块。MXFP8 把粒度降到 32 元素块、块内共享 E8M0 因子 $s_b=\\max_{j\\in b}|x_j|/\\mathrm{FP8}_{\\max}$，正是为吸收这类离群值，但它的适用面有硬边界。</p>\n<p>第一类失效是形状不配合。编解码器卷积层通道数不总是 32 的倍数，补齐会引入无效计算与边界误差，退化为 per-channel 量化又丢掉块级动态范围优势；层维度不能被 32 整除且不宜补齐时，MXFP8 不该作为默认路径。第二类失效是 batch 太小。块缩放因子是每 32 元素一份的元数据，读取与解码开销固定，流式首包的极小 batch 下无法摊薄，吞吐可能低于 BF16 路径——这是元数据带宽与解码开销对 batch 规模的硬约束，不是调参能绕过的。</p>\n<p>第三类失效是敏感层误用。RVQ 码本与输出层必须保留 BF16：块缩放因子的扰动会让码本索引偏移，直接表现为音质突变，这类层的量化误差不体现在张量级统计里，只体现在离散索引上。工程判断因此落在混合精度栈：按层敏感度在 MXFP8 与 MXINT8 间选择，非 32 倍数通道退化处理，小 batch 首包路径不单独依赖 MXFP8 提速。它解决的是大 batch 前向下的动态范围与吞吐兼顾，不解决形状不规整、超小 batch 与离散码本层的精度安全问题。</p>\n<table class=\"mini\"><thead><tr><th>条件</th><th>MXFP8 是否适用</th><th>系统代价</th></tr></thead><tbody><tr><td>层维度 32 整除、大 batch 前向</td><td>适用</td><td>元数据可摊薄，带宽与显存下降</td></tr><tr><td>通道数非 32 倍数</td><td>需补齐或退化 per-channel</td><td>无效计算、边界误差</td></tr><tr><td>超小 batch 流式首包</td><td>不宜单独依赖</td><td>解码开销无法摊薄，吞吐不升反降</td></tr><tr><td>RVQ 码本与输出层</td><td>不适用，保留 BF16</td><td>避免码本索引偏移</td></tr></tbody></table>\n<h3 id=\"alg-mx-fp8-codec-sec-8\">八 · 权重侧：离线分块与 E8M0 因子的生成</h3>\n<p>MXFP8 的第一步发生在推理之前，落在权重上。给定一张形状为 <em>[K, N]</em> 的线性层权重或卷积核，编解码器路径先把它沿内层维度切成 32 元素一块——这是 MX 格式的硬约束，块长不可调。对每块 <em>b</em> 统计 <em>max<sub>j∈b</sub>|x<sub>j</sub>|</em>，据此生成共享缩放因子。工程实现上因子不是任意浮点，而是 E8M0：只有 8 位指数、无尾数，取值被钉在 2 的整数次幂上，因此生成过程本质是一次 <em>floor(log<sub>2</sub>)</em> 截断而非除法。</p>\n<div class=\"formula\">$$s_b = 2^{\\lfloor \\log_2 \\max_{j\\in b}|x_j| \\rfloor},\\quad \\hat{x}_i = \\mathrm{FP8}\\!\\left(\\frac{x_i}{s_b}\\right),\\quad \\text{err}\\le \\frac{s_b}{2}\\sqrt{32}$$</div>\n<p>这一步的输出是两份数据：FP8 的块内量化值（每元素 1 字节）与每 32 元素一个字节量级的 E8M0 因子。代价直接体现在显存上——相对 BF16 权重，MXFP8 把权重体积压到约四分之一，额外元数据只占约 1/32，合计约 0.28 字节/元素的重构开销。但生成不是免费的：离线量化要对每个块做一次归约求最大值，再对每元素做一次缩放与舍入，卷积核通道数不是 32 的倍数时还必须补齐到块边界，补齐部分填零会引入无效乘加，边界块的因子被零值污染后还会略微放大该块的量化误差。这是权重侧必须接受的第一个工程判断：补齐还是退化为 per-channel。</p>\n<p>具体例子：一个声学模型的前馈层内维为 768，恰好 24 个整块，量化干净；而某编解码器卷积层通道数为 100，需补到 128 才能凑成 4 个块，多出的 28 个通道在 Tensor Core 上照样参与计算，吞吐账面上去了，有效算力却打了折。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-9\">九 · 激活侧：逐 token 分块与在线因子</h3>\n<p>激活不能离线预处理，因子必须在运行时现算。请求进入编码器或声学模型前向时，每个 token 的隐状态向量按同样 32 元素切块，块内求最大绝对值、取 E8M0 因子、量化到 FP8。与权重不同的是，激活的分布随 token 剧烈变化——静音帧与爆破音帧的动态范围差出若干数量级，per-tensor 缩放正是死在这里：一个离群通道会把整层的有效位吃掉。块级缩放把这种波动限制在 32 个元素内。</p>\n<p>在线步骤的代价是延迟与带宽的双重开销。每个激活块要一次归约（求 max）、一次指数提取、一次缩放乘法和一次 FP8 舍入，这些操作发生在 Tensor Core 主循环之外，属于纯标量/向量路径，无法被 MMA 掩盖。更关键的是元数据流：因子要随激活一起写入片上或 HBM，再在累加后被读回。设序列长度为 <em>T</em>、隐维为 <em>D</em>，激活因子字节数为 <em>T·D/32</em>，相对 FP8 激活本体的 <em>T·D</em> 是 3% 量级的附加流量，但在小 batch、短序列的首包场景下，这点流量与解码指令的固定开销无法被摊薄，反而成为关键路径。</p>\n<p>伪代码思路：对每个 token 向量 <code>v</code>，<code>for blk in chunks(v, 32): m = max(abs(blk)); e = floor(log2(m)); q = fp8(blk * 2^-e)</code>，因子 <code>e</code> 与 <code>q</code> 一并送入后续 MMA。注意这里没有除法，只有指数位移，这正是 E8M0 选型的目的——把缩放变成位操作，减少标量指令占用。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-10\">十 · Tensor Core 主循环：操作数读取与累加后统一缩放</h3>\n<p>进入 tcgen05 的 MMA 阶段，Blackwell 的 Tensor Core 原生识别 MXFP8 操作数格式，直接按块读取 FP8 尾数与 E8M0 指数，不需要软件先把数据解压成 BF16。这是整条链路里唯一真正吃到硬件红利的位置：MMA 的吞吐按 FP8 计，接近 INT8 档位，而精度损失小于 per-tensor FP8。</p>\n<p>关键机制在于缩放的应用时机。块因子不参与乘加内部的逐元素运算，而是在累加完成后统一施加：</p>\n<div class=\"formula\">$$y = \\sum_{b} s_b^{(w)} s_b^{(x)} \\sum_{i\\in b} \\hat{w}_i \\hat{x}_i$$</div>\n<p>也就是说，内层累加在纯 FP8 域完成，两个块因子在部分和层面相乘后回乘。这带来一个必须正视的数值代价：累加器必须留出足够位宽容纳未缩放的 FP8 乘积和，否则块间尺度差异会在累加中溢出或下溢。工程上通常用 FP32 累加器承接，代价是 TMEM 占用上升——每个输出 tile 的累加缓冲从 FP16 翻倍到 FP32，直接压缩了可并发的 tile 数量，进而影响 2-SM MMA 的配对调度余量。</p>\n<p>具体例子：一个 <em>M=128, N=256, K=768</em> 的线性层，K 方向 24 个块，权重与激活各 24 个因子。若把因子提前乘进操作数，等于把 FP8 乘加退化成需要 BF16 中间表示的路径，Tensor Core 吞吐立刻掉档；正确做法是让 24 组因子在累加后以 24 次乘加合并，代价是每输出元素多 24 次标量乘——在 <em>N=256</em> 的 tile 上这部分被摊薄到可忽略，但在 <em>N=8</em> 的小输出层上就是主导开销。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-11\">十一 · 敏感层旁路：RVQ 码本与输出层保留 BF16</h3>\n<p>并非所有张量都走 MXFP8。RVQ 码本与最终输出层被显式排除在块缩放之外，保留 BF16。原因是机制性的：码本索引是离散查表，块缩放因子对码本向量的扰动不是均匀的数值噪声，而是让最近邻搜索的排序发生翻转——索引一旦偏移，合成音频出现音素错位或音质突变，这类错误无法靠后续层吸收。</p>\n<p>这一步在数据流上是分支：主干走 MXFP8 的层输出 FP32 累加结果，转 BF16 后进入码本查表与输出投影；旁路层则全程 BF16。代价是显存与带宽的不对称——码本通常占参数量的可观份额，保留 BF16 意味着这部分压缩收益归零，整体权重压缩比从 4× 回落到 3× 量级。同时混合精度栈要求 kernel 在层边界做格式切换，每次切换是一次 dtype 转换与一次额外的 TMEM/寄存器搬运，层数多时这些边界开销累积成不可忽视的固定成本。</p>\n<p>具体例子：一个 RVQ 三层码本、每层 1024 项、维度 128 的配置，若误用块缩放量化，单层码本内相邻项的欧氏距离被因子扰动后可能小于量化误差，检索结果在帧间抖动，听感上是周期性爆音。把这三层钉死在 BF16，代价是这部分显存不压缩，收益是索引稳定性。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-12\">十二 · 混合精度栈的层间编排与 batch 依赖</h3>\n<p>按层敏感度在 MXFP8 与 MXINT8 之间选择，构成混合微缩放精度栈。MXINT8 与 MXFP8 共享 32 元素块与 E8M0 因子的骨架，差别在块内表示：整数格式对权重这种分布集中的张量更省，浮点格式对激活这种动态范围大的张量更稳。编排逻辑是逐层标定的：对量化后输出与 BF16 参考的偏差超过阈值的层，升级到 MXFP8 或直接退回 BF16；对偏差可忽略的层，降级到 MXINT8 换取更低的解码开销。</p>\n<p>这一步的系统代价是编译期与运行期的双重耦合。层精度组合在引擎构建时固定，意味着同一份权重针对不同 batch 形态可能要出多套引擎；运行期则要求调度器知道当前 batch 大小，因为块缩放的元数据开销与 batch 强相关。设单次前向的固定解码开销为 <em>c</em>、每样本有效计算为 <em>u</em>、batch 为 <em>B</em>，则 MXFP8 相对 BF16 的净收益近似为：</p>\n<div class=\"formula\">$$\\text{speedup} \\approx \\frac{4uB}{uB + cB + c_{\\text{meta}}}$$</div>\n<p>其中 <em>c<sub>meta</sub></em> 是因子读取与解码的固定成本，不随 <em>B</em> 线性增长。batch 越大，分母中固定项占比越小，收益越接近理论上限；batch 趋近 1 时，<em>c<sub>meta</sub></em> 主导，MXFP8 吞吐可能低于 BF16 路径。这解释了为什么流式 TTS 的首包请求不宜单独依赖 MXFP8 提速——首包天然是小 batch、短序列，正是公式里最不利的角落。</p>\n<p>具体例子：离线音频编码批处理，batch 取到数十条、序列长度上千，因子开销被彻底摊薄，MXFP8 的吞吐接近 INT8 档位；而同一条模型切到实时对话的首包路径，batch 为 1、chunk 只有几十毫秒，因子解码进入关键路径，端到端首包延迟不降反升。工程判断因此落在调度侧：把 MXFP8 的收益绑定在大 batch 的预填与离线批上，首包路径要么走 BF16 旁路，要么用连续批处理把多个请求的首包拼成一个足够大的 batch 再进 MXFP8 主循环。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-13\">十三 · 边界条件：块粒度与 batch 摊薄决定 MXFP8 能否落地</h3>\n<p>把机制拆到数据流上，MXFP8 的每一步都带一个隐含前提：块内元素数恰好是 32，且块数足够多到让元数据成本被摊薄。权重与激活先按 32 元素分块、统计块内最大绝对值、算出共享 E8M0 缩放因子、块内量化为 FP8，这条链在 Tensor Core 读操作数时还要多走一步——块缩放因子在累加完成后统一应用。公式写为 <span class=\"formula\">$$x_i \\approx s_b \\cdot q_i,\\quad s_b = \\frac{\\max_{j\\in b}|x_j|}{\\mathrm{FP8}_{\\max}}$$</span> 其中 $b$ 是 32 元素块。注意 $s_b$ 是 E8M0 格式，只有 2 的幂次，这意味着缩放因子的选择本身带一次取整，块内 FP8 的有效位会被这个取整进一步压缩。当块内最大值恰好落在两个 2 的幂之间时，缩放因子向上取整会让块内小值损失一位精度，向下取整则可能让最大值溢出到 FP8 饱和区——这是块级缩放相对 per-tensor 缩放新增的一层误差来源，也是敏感层必须退化的直接原因。</p>\n<p>第一个失效条件是维度不规整。编解码器卷积层的通道数不总是 32 的倍数，补齐到 32 会引入无效计算与边界误差：补零元素参与块内最大值统计，会把 $s_b$ 抬高，反而压低真实通道的有效位；不补齐则只能退化为 per-channel 量化，块级动态范围优势丢失。工程判断是：对通道数能被 32 整除的层走 MXFP8，对不规整层直接 per-channel 或保留 BF16，不要用补齐硬凑——补齐带来的边界误差在音频重建里表现为高频段的量化噪声抬升，比 per-channel 的精度损失更难听出来但更难调试。同理，RVQ 码本与输出层必须保留 BF16，块缩放因子对码本向量的扰动会导致索引偏移，合成音频出现音素错位或音质突变，这类错误不可逆，不能靠后处理修。</p>\n<p>第二个失效条件是小 batch。块缩放因子的元数据量为每 32 元素一个字节量级，解码这些因子本身要占指令与寄存器带宽。设单层权重元素数为 $N$，则元数据开销约为 $N/32$ 字节，相对权重的压缩比收益是 $(2\\text{ bytes}\\rightarrow1\\text{ byte})/32$ 量级——只有在一次前向里被足够多的 token 复用，这笔固定开销才摊得薄。流式 TTS 的首包场景 batch 极小，元数据读取与解码开销无法摊薄，MXFP8 吞吐可能低于预期甚至不如 BF16 路径；而离线音频编码批或 chunk 批量前向里，batch 越大摊薄越充分，收益才显现。系统代价上，这直接改写容量规划：MXFP8 的吞吐曲线对 batch 敏感，不能按 per-tensor FP8 的线性假设去估 SLO，首包延迟约束下应把 MXFP8 只用于 decode 阶段的大 batch 线性层，prefill 或首包路径保留 BF16 或 per-channel。</p>\n<table class=\"mini\"><thead><tr><th>步骤</th><th>输入</th><th>输出</th><th>系统代价</th></tr></thead><tbody><tr><td>分块统计</td><td>FP16/BF16 权重或激活</td><td>每 32 元素块的最大绝对值</td><td>一次归约，占带宽</td></tr><tr><td>算 E8M0 因子</td><td>块内最大值</td><td>2 的幂次缩放因子</td><td>取整误差，敏感层需退化</td></tr><tr><td>块内量化</td><td>块元素与因子</td><td>FP8 操作数 + 元数据</td><td>权重显存与带宽压缩</td></tr><tr><td>Tensor Core 读</td><td>MXFP8 操作数</td><td>累加结果</td><td>原生 MX 格式吞吐接近 INT8</td></tr><tr><td>累加后应用因子</td><td>累加值与 $s_b$</td><td>恢复尺度的输出</td><td>解码开销随块数增长</td></tr></tbody></table>\n<p>第三个边界是精度栈的混合选择本身带来调度代价。按层敏感度在 MXFP8 与 MXINT8 间切换，意味着同一张图里存在多种量化格式的算子，kernel 选择、权重布局与元数据排布都要分路径处理，编译期与运行期的分支判断会吃掉一部分本应属于计算的带宽。MXINT8 的块内表示是定点，缩放因子同样按 32 元素共享，但定点对块内分布的假设更强，适合激活分布集中的线性层；MXFP8 的动态范围更宽，适合卷积与声学模型里分布跨度大的层。混合栈的正确用法是把敏感度判断前置到离线校准阶段，固化每层的格式选择，而不是在推理时动态探测——动态探测会引入额外统计开销，且在小 batch 下与元数据开销叠加，把收益彻底抵消。规模上限因此不在单卡算力，而在块缩放元数据的带宽与解码开销：层维度能被 32 整除、batch 足够大、敏感层已退化，三个条件同时满足时 MXFP8 才值得开；缺一个就该回到 per-channel 或 BF16，这是工程上比追求格式覆盖率更稳的判断。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-14\">十四 · 缩放因子的取整与误差上界</h3>\n<p>核心公式里最容易被略过的一步是 $s_b$ 的取整。若按 $\\max_j|x_j|/\\mathrm{FP8}_{\\max}$ 直接算，$s_b$ 是任意实数，硬件无法在 Tensor Core 的块缩放通路里高效应用；OCP MX 规定缩放因子为 E8M0，即只有 8 位指数、无尾数，取值被约束为 $2^e$。于是实际取</p>\n<div class=\"formula\">$$s_b = 2^{\\lceil \\log_2(\\max_{j\\in b}|x_j|/\\mathrm{FP8}_{\\max})\\rceil},\\qquad q_i = \\mathrm{round}_{\\mathrm{FP8}}(x_i/s_b)$$</div>\n<p>取上整而非下整是关键一步：向上取整保证 $|x_i/s_b| \\le \\mathrm{FP8}_{\\max}$，块内不会因缩放不足而溢出；代价是缩放因子最多比理想值大一倍，块内有效位被系统性压低一档。这就是误差项 $\\mathrm{err}\\le \\frac{s}{2}\\sqrt{32}$ 的来源——每元素舍入误差不超过 $s/2$，32 个元素独立舍入后按欧氏范数累积得 $\\sqrt{32}$ 倍。注意该上界随 $s_b$ 线性增长，所以离群值真正伤害精度的路径不是“撑爆格式”，而是“把 $s_b$ 抬到下一个 2 的幂，让同块其余 31 个元素一起损失一位”。这也解释了为什么块级缩放优于张量级：张量级只有一个 $s$，一个离群值抬高 $s$ 会波及整张量；块级只波及 32 元素。</p>\n<p>工程代价落在元数据上：每 32 个 FP8 元素（32 字节）配 1 字节 E8M0，元数据开销约 3.1%，但读取是分散的——每个块的缩放因子要和块数据一起进 SMEM 再喂给 MMA，小 batch 时这部分解码指令与访存延迟摊不薄。举例：一个 $4096\\times4096$ 的声学模型线性层，权重 16 MB 量级，块缩放因子约 128 KB 量级，单看带宽不大，但在 decode 阶段每步只算一个 token 时，读元数据的固定开销与读权重的比例失衡，这正是小 batch 收益被抵消的机制根源。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-15\">十五 · 累加后统一应用缩放因子的推导</h3>\n<p>推理时“块缩放因子在累加后统一应用”不是实现偷懒，而是数学上可交换的必然结果。设点积 $\\sum_i x_i y_i$，两侧各自按块量化：$x_i = s^x_{b(i)} q^x_i$，$y_i = s^y_{b(i)} q^y_i$。若 $x$ 与 $y$ 的 32 元素分块边界对齐（沿 K 维同步切块），则</p>\n<div class=\"formula\">$$\\sum_i x_i y_i = \\sum_{b}\\Big(s^x_b s^y_b \\sum_{i\\in b} q^x_i q^y_i\\Big)$$</div>\n<p>块内乘积 $q^x_i q^y_i$ 可直接送进 FP8 MMA 累加器，块外只多一次标量乘 $s^x_b s^y_b$。这就是 MXFP8 能在 Blackwell tcgen05 上跑出接近 INT8 吞吐的结构性原因：Tensor Core 内部只做定点的块内乘加，缩放恢复被推迟到累加之后、以极低频率（每 32 个 MAC 一次）执行。推导的关键前提是<b>分块边界对齐</b>——若权重按 K 维 32 元素切块而激活按不同偏移切块，上式不再成立，必须回退到逐元素缩放，吞吐立刻塌掉。因此 MXFP8 的 kernel 必须强制 K 维按 32 对齐，这也是后面通道补齐问题的数学根源。</p>\n<p>代价是累加精度：块内累加在 FP32 累加器里做，块间乘 $s^x_b s^y_b$ 后再累加，若块数很多（K 很大），块间求和的动态范围由各块 $s$ 的差异决定，E8M0 的指数跨度足够覆盖，但每块一次标量乘在 K=8192 时是 256 次额外乘加，相对 8192 次 MAC 约占 3%，与元数据开销同量级。对卷积层，K 为通道数乘核面积，块数更多，这部分开销在大 batch 下被 MMA 吞吐掩盖，在小 batch 下则直接体现在 kernel 时长上。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-16\">十六 · 分块与量化的可实现伪代码</h3>\n<p>把上述推导落到一个可实现的量化 kernel，需要处理三件事：尾部块、E8M0 取整、以及 FP8 饱和。伪代码思路如下（以权重预量化为例，激活在运行时同构处理）：</p>\n<ul>\n<li>沿最后一维（K 维）以 32 为步长遍历，块内用向量化 max-reduce 求 $\\max_j|x_j|$；</li>\n<li>由 $\\max$ 与 $\\mathrm{FP8}_{\\max}$ 之比取 $\\lceil\\log_2(\\cdot)\\rceil$ 得指数 $e$，钳制到 E8M0 可表示范围，写 1 字节元数据；</li>\n<li>计算 $1/s_b = 2^{-e}$（E8M0 的倒数仍是 2 的幂，可用指数取负实现，避免除法）；</li>\n<li>逐元素乘 $2^{-e}$ 后做 FP8 round-to-nearest-even，并饱和到 $\\pm\\mathrm{FP8}_{\\max}$；</li>\n<li>若 K 不是 32 的倍数，尾部块单独处理：要么补齐到 32（填零，量化后零不引入误差但引入无效 MAC），要么该块退化为一组 per-channel 缩放。</li>\n</ul>\n<p>这里有一个易错的数值细节：$\\max_j|x_j|=0$ 的块（ReLU 后的死通道、padding 区）会让 $\\log_2$ 发散，实现上必须给指数设下界，否则整块缩放因子变成非法值，反量化时污染下游。另一个细节是 round-to-nearest-even 与饱和的顺序——必须先舍入再饱和，否则饱和后的值再舍入可能越界。</p>\n<p>系统代价体现在预量化阶段：权重一次性离线量化，成本可摊；激活必须每步在线量化，其 kernel 与 MMA kernel 之间的同步是流式推理的额外延迟项。对 chunk 批量的流式 TTS，激活量化 kernel 的启动开销在 chunk 较小时占比上升，工程上常把量化融进前一个算子的 epilogue，用 producer-consumer 的 warp 分工把量化延迟藏在 MMA 之后。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-17\">十七 · 通道补齐的代价模型</h3>\n<p>编解码器卷积层通道数不总是 32 的倍数，这是 MXFP8 在该领域最现实的摩擦点。设通道数 $C$，补齐到 $C' = 32\\lceil C/32\\rceil$，无效计算比例为</p>\n<div class=\"formula\">$$\\rho = \\frac{C'-C}{C'} = \\frac{32\\lceil C/32\\rceil - C}{32\\lceil C/32\\rceil}$$</div>\n<p>$C=48$ 时 $\\rho=1/2$，一半 MAC 打在零上；$C=80$ 时 $\\rho=1/5$；$C$ 越接近 32 的倍数，浪费越小。但补齐不只是算力浪费：填零通道的权重若被量化，其块内 $\\max$ 由真实通道决定，零元素不改变 $s_b$，所以数值上安全；真正的边界误差来自<b>卷积核在通道维的滑动窗口与 32 分块边界不对齐</b>——当卷积沿通道维做分组或深度可分离时，一个 32 元素块可能横跨两组通道，块内共享缩放就把两组不同动态范围的数据强行绑在一起，误差上界 $\\frac{s}{2}\\sqrt{32}$ 中的 $s$ 由两组中较大的那个决定，小动态范围那组被过度压缩。此时退化为 per-channel 量化能保住每组自己的尺度，但丢失块级缩放对离群值的吸收能力，是精度与吞吐之间的真实取舍，不是免费的降级路径。</p>\n<p>工程判断：对通道数规整（32 倍数）的骨干层走 MXFP8，对 $C$ 落在 $[32k+1, 32k+16]$ 这种“补齐浪费超过 1/3”的层，优先考虑 per-channel MXINT8 或直接 BF16，把补齐的无效 MAC 换成更细的量化粒度。这一层选择应按层敏感度离线标定，而不是全局一刀切。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-18\">十八 · 混合精度栈的敏感度判据</h3>\n<p>RVQ 码本与输出层保留 BF16 的理由可以从公式直接读出：码本索引是离散查表，量化误差不体现在数值大小上，而体现在<b>最近邻归属的翻转</b>。设码本向量 $c_k$ 与查询 $z$，量化后 $z' = z + \\epsilon$，若 $\\|z-c_k\\|$ 与 $\\|z-c_{k'}\\|$ 的差距小于 $\\|\\epsilon\\|$，索引就从 $k$ 翻到 $k'$，合成音频出现音素错位。块缩放引入的 $\\epsilon$ 上界是 $\\frac{s_b}{2}\\sqrt{32}$，在码本这种高维稠密向量上，相邻码字间距往往与这个量级可比，翻转概率不可忽略。输出层同理：logits 的微小扰动经 softmax 放大后改变采样结果。</p>\n<p>敏感度判据可写成每层的信噪比门限：对层 $l$，比较量化误差功率与信号功率，</p>\n<div class=\"formula\">$$\\mathrm{SNR}_l = 10\\log_{10}\\frac{\\mathbb{E}[x^2]}{\\mathbb{E}[\\epsilon^2]},\\qquad \\epsilon^2 \\le \\frac{s_b^2}{4}\\cdot 32$$</div>\n<p>当 $\\mathrm{SNR}_l$ 低于该层任务容忍门限（码本层与输出层门限最严），该层退出 MXFP8。这个判据把“按层敏感度选择 MXFP8 或 MXINT8”从经验说法变成可计算的离线标定流程：逐层跑校准集，算 $\\mathrm{SNR}_l$，按门限分档。代价是混合精度栈让 kernel 调度复杂化——同一模型里 MXFP8 与 BF16 层交替，图切分与 kernel launch 次数上升，在小 batch 流式首包场景下，切换开销可能吃掉 MXFP8 层省下的时间，这也是超小 batch 不宜单独依赖 MXFP8 提速的机制解释。</p>\n<p>最后落到一个具体机制上：Blackwell 的 tcgen05 MMA 对 MXFP8 操作数的块缩放因子有硬件通路，但该通路要求操作数在 SMEM 中按 32 元素块对齐布局，且缩放因子与数据块同址排布。这意味着量化 kernel 的输出布局必须与 MMA 的期望布局一致，否则运行时要做一次重排，重排的带宽开销会把块级缩放省下的显存带宽优势抹平。实现上把量化与布局重排融进同一个 epilogue，是让 MXFP8 在编解码器推理里真正兑现吞吐的前提。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-19\">十九 · 块缩放的三条边界：何时 MXFP8 反而更慢、更不准</h3>\n\n<p>先看公式里被忽略的那一项。块缩放恢复数值的表达式为 <span class=\"formula\">$$x_i \\approx s_b \\cdot q_i,\\quad s_b = \\frac{\\max_{j\\in b}|x_j|}{\\mathrm{FP8}_{\\max}}$$</span>，其中 $b$ 是 32 元素块。推导的关键一步不在量化本身，而在<b>缩放因子必须与块内最大值同步更新</b>：一旦 $s_b$ 取整到 E8M0 的 2 的幂，块内最大元素的量化误差就不再由尾数决定，而由 $s_b$ 与真实最大值之间的比值决定。若某块最大值恰好落在两个 2 的幂之间，E8M0 只能向上取整，块内所有元素的有效位被整体压低一档；向下取整则可能溢出。这一步决定了 MXFP8 的精度上限不是 FP8 的尾数宽度，而是<b>块内动态范围的分布形状</b>——块内元素幅度越均匀，取整损失越小；块内存在单个离群值时，其余 31 个元素被迫共享一个偏大的 $s_b$，有效位被系统性浪费。这正是 per-tensor FP8 失效的同一机理，只是被压缩到 32 元素尺度上，因此 MXFP8 并不能\"消除\"离群值问题，只能把它的影响半径从整张量缩小到单个块。\n\n<p>由此得到第一条边界：<b>块内幅度分布比块大小更重要</b>。对编解码器卷积层，权重在通道方向上往往呈现明显的长尾——少数通道幅度远大于其余通道。若按 32 元素沿通道维分块，长尾通道会独占若干块并把 $s_b$ 抬高，而与之同块的普通通道精度下降；若改为沿空间维分块，同一通道内的权重幅度更接近，取整损失显著减小。这意味着分块轴向的选择是一个必须显式建模的推理系统参数，而不是数据格式自带的固定行为。工程上的判据是：统计每块内 $\\max_j|x_j| / \\mathrm{median}_j|x_j|$ 的比值，比值大的层不适合直接套用 MXFP8，应退化为 per-channel 量化或保留 BF16。这一步不需要训练，只需一次离线校准，但必须在精度栈定型前完成，否则线上出现的音质退化无法归因。\n\n<p>第二条边界是元数据开销在小 batch 下不可摊薄。每 32 元素一个 E8M0 字节，意味着权重侧元数据占比约为 $1/32$ 的字节数——对权重显存是可控的，但对<b>激活</b>侧是另一回事：激活在每个 chunk 前向时都要重新计算 $s_b$，这要求先做一次块内归约求最大值，再量化，再让 Tensor Core 读取。归约本身是一次额外的读带宽与同步，其代价与块数成正比、与 batch 无关。于是存在一个吞吐交叉点：设单次前向的量化开销为 $C_q$（与块数成正比），Tensor Core 计算时间为 $C_c \\cdot B$（与 batch 成正比），则 MXFP8 相对 BF16 的净收益约为 $(C_c^{BF16} - C_c^{MX})B - C_q$。batch 越小，$C_q$ 越难被摊薄，流式 TTS 的首包 chunk 正是 $B$ 极小的场景。此时正确做法不是硬上 MXFP8，而是<b>按请求形态分流</b>：首包 chunk 走 BF16 或 per-channel FP8 保延迟，后续稳定 chunk 走 MXFP8 摊薄开销；离线音频编码批则整批走 MXFP8。\n\n<p>第三条边界是形状不规整带来的补齐代价，以及它对敏感层的连带风险。编解码器卷积层通道数不总是 32 的倍数，补齐到 32 的整数倍会引入无效计算，且补齐位置的填充值会参与 $\\max_j|x_j|$ 的归约——若填充值取零则无影响，若取边界复制值则可能人为抬高 $s_b$，把整块的精度拉低。更危险的是 RVQ 码本与输出层：这两处的量化误差不表现为数值噪声，而表现为<b>索引偏移</b>——码本向量在块缩放后发生微小扰动，最近邻搜索的胜者改变，合成音频出现音素错位或音质突变。这类失效不会在困惑度或重构误差上显现，只能靠端到端音频指标或人工听测捕获。因此精度栈的划分必须按层敏感度而非按算子类型：卷积与线性层的大 batch 前向走 MXFP8，码本查表与输出投影固定 BF16，中间层可在 MXFP8 与 MXINT8 间按校准结果选择。下表给出这一划分的工程判据。\n\n<table class=\"mini\"><thead><tr><th>层类型</th><th>推荐精度</th><th>判据</th><th>失效表现</th></tr></thead><tbody><tr><td>卷积（通道 32 倍数）</td><td>MXFP8</td><td>块内幅度比小、batch 可摊薄</td><td>数值噪声，可测</td></tr><tr><td>卷积（通道不规整）</td><td>per-channel FP8 或 BF16</td><td>补齐引入边界误差</td><td>边界帧失真</td></tr><tr><td>声学模型线性层</td><td>MXFP8 / MXINT8</td><td>按校准敏感度选</td><td>音素概率偏移</td></tr><tr><td>RVQ 码本、输出层</td><td>BF16</td><td>索引稳定性优先</td><td>音素错位、音质突变</td></tr></tbody></table>\n\n<p>把三条边界合起来看，MXFP8 在 Blackwell 上的适用域是一个<b>由形状、batch、层敏感度三者共同约束的可行域</b>，而非一个默认开关。可行域内它把权重显存与带宽压到接近 INT8 的水平并保留块级动态范围；可行域外，元数据解码开销与补齐误差会同时侵蚀吞吐与精度，此时退化为 per-channel 量化虽然丢掉块级动态范围优势，却换回了可预测的延迟与无补齐的计算图。工程判断的落点是：先离线算出每层的块内幅度比与通道整除性，再按请求形态的 batch 分布决定哪些层进 MXFP8，把 RVQ 码本与输出层锁死在 BF16，最后用首包延迟与实时率两个 SLO 指标验证交叉点是否落在实际流量分布的正确一侧。</p>\n\n</p></p></p></p>\n<h3 id=\"alg-mx-fp8-codec-sec-20\">二十 · 请求形态：MXFP8 只在大块前向里兑现吞吐</h3>\n<p>MXFP8 的收益结构由块缩放元数据决定：每 32 元素共享一个 E8M0 缩放因子，Tensor Core 读操作数时缩放因子在累加完成后统一应用。这意味着一次 MMA 指令覆盖的元素越多、块数越多，元数据解码与缩放应用的固定开销被摊得越薄。因此它天然匹配的请求形态是“大块前向”——流式 TTS 中按 chunk 聚合的批量合成、离线音频编码批、声学模型线性层的整批前向。这类请求的特征是同一时刻有大量相互独立的序列需要过同一组卷积与线性层，batch 维度足以把每层每块的缩放因子读取次数压到可忽略。</p>\n<p>反过来，请求形态若是“单条流、低并发、逐帧推进”，每个 chunk 只有一条或几条序列，MXFP8 的每块元数据读取与解码就变成纯开销：Tensor Core 的算力利用率上不去，而缩放因子的加载却按块数线性增长。此时 BF16 路径反而更稳——它没有块元数据，也没有块内量化误差，单条流的首包延迟更可控。判断标准可以写成一个粗略的摊薄比：设单次前向的块数为 $N_b$，每块元数据开销为 $c_m$，则有效算力占比近似为</p>\n<div class=\"formula\">$$\\eta \\approx \\frac{N_b \\cdot T_{\\text{mma}}}{N_b \\cdot T_{\\text{mma}} + N_b \\cdot c_m} = \\frac{T_{\\text{mma}}}{T_{\\text{mma}} + c_m}$$</div>\n<p>其中 $T_{\\text{mma}}$ 是单块 MMA 的有效计算时间。$N_b$ 在分子分母同时出现，说明单纯增加块数并不改变占比——真正改变占比的是每块承载的元素量，也就是 batch 与序列长度共同决定的块内有效工作量。这就是为什么负载配方里 batch 大小是首要变量，而不是模型规模。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-21\">二十一 · 长度分布：短序列堆块、长序列摊块</h3>\n<p>长度分布对 MXFP8 的影响体现在两个层面。第一，序列长度决定单次前向里激活张量的形状：短序列（几十帧的 chunk）在 batch 拼批后仍能形成足够大的二维张量，块划分沿通道维进行，32 元素块的数量由通道数决定而非序列长度；此时 batch 是唯一的摊薄手段。第二，长序列（整段音频编码、长文本条件的声学前向）本身就能提供大张量，即使 batch=1 也能让每层产生大量 32 元素块，元数据开销被序列维度摊薄。因此负载配方应把“长序列离线批”和“短 chunk 高并发流式”分开配置：前者可以低 batch 跑 MXFP8，后者必须靠连续批处理把并发拉起来。</p>\n<p>长度分布还有一个隐蔽代价：变长序列拼批需要 padding，padding 出来的无效 token 同样参与块划分与量化，产生无效计算与边界误差。对通道数非 32 倍数的卷积层，补齐到 32 的倍数会进一步放大这部分无效工作量。工程上的做法是按长度分桶拼批，把长度相近的请求放进同一批，减少 padding 比例；分桶粒度太细会增加调度开销，太粗则 padding 浪费，需要在连续批处理的调度器里设一个长度方差阈值。</p>\n<ul>\n<li>短 chunk、高并发：MXFP8 收益依赖 batch 摊薄，必须配合连续批处理。</li>\n<li>长序列、低并发：序列维度自带摊薄，MXFP8 可直接用，但要注意 padding 与通道补齐。</li>\n<li>混合长度：分桶拼批，控制 padding 比例，否则块级量化的边界误差会在补齐区累积。</li>\n</ul>\n\n<h3 id=\"alg-mx-fp8-codec-sec-22\">二十二 · 并发与批大小：收益曲线的拐点</h3>\n<p>把 MXFP8 的吞吐写成 batch 的函数，可以看到一个明显的拐点。设每层前向的计算量为 $B \\cdot L \\cdot C$（batch、序列长度、通道数），块数为 $B \\cdot L \\cdot C / 32$，元数据开销与块数成正比，而 MMA 有效计算也与块数成正比但每块耗时更长。在小 batch 区，固定开销（kernel 启动、缩放因子加载、解码指令）占主导，MXFP8 的吞吐可能低于 BF16；越过拐点后，MXFP8 接近 INT8 的吞吐开始兑现。拐点位置由硬件上的元数据解码吞吐与 MMA 吞吐之比决定，工程上通过实测扫描 batch 从 1 到目标并发，找到 MXFP8 吞吐超过 BF16 的最小 batch，把它作为调度器的准入阈值。</p>\n<p>并发层面还要区分“请求并发”与“批内并发”。分离式预填/解码架构下，预填阶段天然是大 batch 大序列，适合 MXFP8；解码阶段每步只处理一个 token，batch 由并发请求数决定，若并发不足，解码侧的 MXFP8 收益会被每步的元数据开销吃掉。因此负载配方常见做法是：预填走 MXFP8，解码按并发数动态选择 MXFP8 或 BF16 路径，形成按阶段切换的精度栈。这与按层敏感度选择 MXFP8/MXINT8 的混合栈是同一思路的两个维度——一个按数据流阶段切，一个按层切。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>batch 特征</th><th>MXFP8 适配判断</th><th>主要代价</th></tr></thead><tbody><tr><td>离线音频编码批</td><td>大 batch、长序列</td><td>适配，摊薄充分</td><td>padding 与通道补齐</td></tr><tr><td>流式 TTS chunk 批</td><td>中高并发、短 chunk</td><td>需连续批处理拉并发</td><td>首包延迟受元数据开销影响</td></tr><tr><td>单条流逐帧</td><td>batch=1</td><td>不适配，退 BF16</td><td>元数据开销无法摊薄</td></tr><tr><td>解码阶段低并发</td><td>小 batch 每步一 token</td><td>按并发动态切换</td><td>每步固定开销占比高</td></tr></tbody></table>\n\n<h3 id=\"alg-mx-fp8-codec-sec-23\">二十三 · 负载不对时的三种失效</h3>\n<p>第一种失效是小 batch 流式首包。块缩放因子的元数据读取与解码开销在每层每块上重复，batch 不足时这部分开销与 MMA 时间同量级，MXFP8 吞吐不升反降，甚至不如 BF16 路径。对 SLO 以首包延迟为约束的流式 TTS，这意味着把 MXFP8 硬塞进低并发路径会直接破坏实时率。工程判断是：首包路径保留 BF16 或 per-channel 量化，等并发爬升后再切 MXFP8。</p>\n<p>第二种失效是通道数不规整。编解码器卷积层通道数不总是 32 的倍数，补齐到 32 会引入无效计算与边界误差；退化为 per-channel 量化又丢失块级动态范围优势，等于放弃了 MXFP8 对抗离群值的核心能力。这条失效在卷积为主的声码器与编解码器前端最常出现，负载配方里应把这类层单独标记，走 per-channel 或 BF16，而不是强行补齐。</p>\n<p>第三种失效是码本与输出层误用块缩放。RVQ 码本与输出层对缩放因子的扰动极其敏感，块缩放引入的索引偏移会让合成音频出现音素错位或音质突变。这类层必须保留 BF16，不能为了统一精度栈而量化。失效的代价不是吞吐，而是正确性——它不会在延迟指标上暴露，只会在听感与下游任务指标上体现，因此负载配方要把“哪些层永不量化”写成硬约束，而不是按 batch 动态决定。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-24\">二十四 · 配方落地：按负载分档的精度栈</h3>\n<p>把上述判断收敛成一张可执行的配方表：按请求形态与并发把服务分成三档，每档给定精度栈与调度策略。高并发离线批走全 MXFP8（码本与输出层 BF16），预填与解码都开；中并发流式走预填 MXFP8、解码按并发阈值切换；低并发单流走 BF16 或 per-channel，MXFP8 仅作为权重存储格式以压缩显存与带宽，计算时反量化。第三档的折中值得注意：权重以 MXFP8 存储能把显存与带宽进一步压缩，计算时反量化回 BF16 虽损失了 Tensor Core 的 FP8 吞吐，但保住了首包延迟，这是显存受限但并发不足时的实用解。</p>\n<p>调度器需要两个观测量来驱动分档：实时并发请求数与批内平均序列长度。前者决定解码侧是否越过 MXFP8 拐点，后者决定 padding 比例与块摊薄程度。把这两个量喂给一个简单的阈值判断，就能在连续批处理的每个调度周期选择精度路径，而不必重启服务或重编译引擎。阈值本身应由实测扫描得出，而不是拍脑袋设定——这正是负载配方与算子实现分离的价值：算子层保证 MXFP8 在正确输入下接近 INT8 吞吐，配方层保证输入始终落在正确区间。</p>\n<p>最后一条工程判断落在通道补齐的边界上：对通道数非 32 倍数的层，补齐带来的无效计算在 batch 大时被摊薄、在 batch 小时被放大，因此补齐策略也应随负载分档——高并发档补齐走 MXFP8，低并发档退 per-channel。补齐与退化不是二选一的全局决策，而是与 batch 绑定的局部决策，这与块缩放元数据“随块变化”的粒度是一致的。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-25\">二十五 · 负载配方：块缩放收益在哪种请求形态下成立</h3>\n<p>MXFP8 的收益不是逐元素算出来的，而是逐块摊出来的。每 32 个元素共享一个 E8M0 缩放因子，意味着每读 32 个 FP8 字节就要附带一次因子读取与一次累加后重缩放；设块大小为 <i>B</i>=32、单块有效载荷字节数为 <i>B</i>、元数据为 1 字节量级，则元数据占比约为 1/(<i>B</i>+1)。这个比例本身很小，但它对应的是独立的解码指令流与寄存器压力，只有在 Tensor Core 的 MMA 流水被足够多的块填满时才会被隐藏。因此负载配方的核心判断只有一条：<b>单次前向里能被连续喂进 MMA 的块数是否足够多</b>。大 batch 的离线音频编码批、流式 TTS 的 chunk 批量前向，正是块数充足、元数据开销被摊薄的形态；反过来，逐请求串行、每步只处理一两条 utterance 的在线解码，块数太少，解码开销直接暴露在关键路径上。</p>\n<p>长度分布决定的是另一件事：块边界与有效计算的比例。编解码器卷积层的通道数不总是 32 的倍数，补齐到 32 会引入无效通道计算，且补齐位置的边界误差会随层数累积；退化为 per-channel 量化则丢掉块级动态范围，回到被局部离群值拖累的老问题上。可用一个粗略的有效率来刻画：<i>η</i> = <i>C</i>/(32·⌈<i>C</i>/32⌉)，<i>C</i> 为通道数。当 <i>C</i> 接近 32 的整数倍时 <i>η</i> 接近 1，补齐代价可忽略；当 <i>C</i> 落在 32 的倍数下方一点（例如刚过 32 的奇数通道），无效计算比例上升，此时应改量化粒度而非硬补齐。声学模型线性层的隐藏维通常规整，是 MXFP8 最安全的落点；卷积层则需要按层逐一核对 <i>η</i>，把不规整的层留在 BF16 或 per-channel。</p>\n<p>并发与批大小的边界可以用一条经验判据表达：设单块解码开销为 <i>t</i><sub>meta</sub>、单块 MMA 时间为 <i>t</i><sub>mma</sub>，则只有当批内并发块数 <i>N</i><sub>b</sub> 满足 <i>N</i><sub>b</sub>·<i>t</i><sub>mma</sub> ≫ <i>t</i><sub>meta</sub> 时，MXFP8 才真正快过 BF16 路径。小 batch 流式首包场景恰好落在不等式另一侧：首包延迟由单次前向的关键路径决定，元数据读取与解码无法被后续块掩盖，吞吐可能低于预期甚至不如 BF16。这类请求应把 MXFP8 限定在预填充或批量编码阶段，解码步保留 BF16 或按层混合。</p>\n<p>负载不对时的失效是分层的，值得用一张小表对照。第一类是形状失效：通道不规整导致补齐无效计算与边界误差；第二类是并发失效：小 batch 下元数据开销无法摊薄，吞吐不升反降；第三类是敏感层误用：对 RVQ 码本与输出层施加块缩放，缩放因子扰动会使码本索引偏移，合成音频出现音素错位或音质突变，这类错误不会表现为数值溢出，而是听感上的突变，排查成本高。工程判断是：把 MXFP8 当作<b>大 batch、规整维度、非敏感层</b>的加速手段，按层敏感度在 MXFP8 与 MXINT8 间选择形成混合栈，而不是把它当作全局默认精度。</p>\n<table class=\"mini\"><thead><tr><th>负载形态</th><th>块数是否充足</th><th>主要代价</th><th>处置</th></tr></thead><tbody><tr><td>离线音频编码大 batch</td><td>充足</td><td>元数据摊薄后可忽略</td><td>权重与激活走 MXFP8</td></tr><tr><td>流式 TTS chunk 批量</td><td>中等</td><td>首包关键路径上的解码开销</td><td>预填充 MXFP8、解码步 BF16</td></tr><tr><td>逐请求小 batch 在线解码</td><td>不足</td><td>吞吐低于 BF16 路径</td><td>不单独依赖 MXFP8</td></tr><tr><td>通道非 32 倍数的卷积层</td><td>不适用</td><td>补齐无效计算与边界误差</td><td>退化 per-channel 或保留 BF16</td></tr></tbody></table>\n<h3 id=\"alg-mx-fp8-codec-sec-26\">二十六 · 硬件档位与并行拓扑的耦合</h3>\n<p>部署 MXFP8 推理时，硬件档位不是“选一张卡”这么简单，而是决定了并行拓扑能否把块缩放元数据的开销摊薄。Blackwell 档位（SM100/SM103）原生支持 MX 格式 Tensor Core，这意味着 MXFP8 操作数可以直接喂进 MMA 流水线，块缩放因子在累加完成后统一应用，不需要在 kernel 外部做一次反量化。但原生支持只解决“算得动”，不解决“喂得饱”：每 32 元素一个 E8M0 缩放因子，意味着权重带宽里混入了约 1/32 的元数据流量，激活侧同理。当并行拓扑把一次前向切得过细，每张卡上的有效 batch 变小，元数据读取与解码的相对占比上升，MXFP8 的吞吐优势就被抵消。</p>\n<p>拓扑选择上，编解码器卷积与声学模型线性层的并行维度并不相同。卷积层沿通道切分时，若通道数不是 32 的倍数，块边界会跨卡，缩放因子必须在卡间对齐，通信量随块数线性增长；线性层沿隐藏维切分则天然对齐到 32 元素块，张量并行（TP）切分后每块的缩放因子仍在本卡内闭合，无需跨卡同步。因此一个可复现的拓扑判断是：把 TP 优先给线性层密集的声学模型主干，卷积密集的编解码器前端尽量放在单卡内做数据并行（DP），避免块边界跨设备。</p>\n<div class=\"formula\">$$\\text{meta\\_ratio} = \\frac{1}{32}\\cdot\\frac{B_{\\text{eff}}}{B_{\\text{eff}}+B_{\\text{w}}},\\quad B_{\\text{eff}} = \\text{batch}\\times\\text{seq}$$</div>\n<p>这里的代价是显性的：元数据占比随有效 batch 下降而上升，小 batch 流式首包场景下 MXFP8 的端到端延迟可能不如 BF16 路径。具体例子：一个流式 TTS 请求在首包阶段只有单条 chunk 进入前向，卷积前端通道补齐到 32 倍数后引入无效计算，块缩放解码开销无法摊薄，此时应让首包走 BF16 或 per-channel 量化路径，等 chunk 批量积累后再切 MXFP8。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-27\">二十七 · 量化方案的混合精度栈</h3>\n<p>单一 MXFP8 覆盖全模型是危险的。RVQ 码本与输出层对缩放因子扰动极其敏感：块缩放因子随块内最大绝对值变化，一旦码本向量落入不同块，缩放因子跳变会让量化后的索引发生偏移，合成音频出现音素错位或音质突变。因此量化方案必须是分层的：卷积与线性层走 MXFP8，RVQ 码本与输出层保留 BF16，形成混合微缩放精度栈。</p>\n<p>层敏感度的判定不靠猜，靠可复现的探针流程：对每一层单独替换为 MXFP8，跑固定校准集，比较输出与 BF16 参考的偏差；偏差超过阈值的层退回 BF16 或 per-channel 量化。MXINT8 作为中间档位，适合那些动态范围够但块内分布偏均匀的层——它保留块级缩放的结构，但块内用整数表示，解码路径更短。选择逻辑可以写成伪代码思路：</p>\n<ul>\n<li>对每层统计通道数是否能被 32 整除；不能整除且补齐代价高的层，直接标记为 per-channel 候选。</li>\n<li>对候选层跑校准前向，记录块内最大绝对值与缩放因子的方差；方差大的层说明块间动态范围跳变剧烈，优先保留 BF16。</li>\n<li>码本类参数与输出投影无条件排除在块缩放之外，避免索引偏移。</li>\n</ul>\n<p>代价体现在显存与带宽的混合账上：MXFP8 把权重显存压到 BF16 的一半左右，但 RVQ 码本与输出层保留 BF16 后，整体显存节省低于纯 FP8 方案；换来的是码本索引稳定，避免合成质量回退带来的重试与重放开销。具体例子：一个多层 RVQ 编解码器，码本层数多、每层码本尺寸大，若误用块缩放，缩放因子扰动会让相邻码本向量的量化索引互换，解码出的音频帧出现周期性爆音；保留 BF16 后该现象消失，代价是这部分权重带宽回到 BF16 水平。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-28\">二十八 · KV 策略与块缩放的交互</h3>\n<p>KV cache 的量化策略与 MXFP8 不是同一件事，但两者在显存预算上直接竞争。MXFP8 压缩的是权重与激活，KV cache 压缩的是历史上下文；若把 KV 也做成块缩放量化，块边界与注意力头维度、序列位置的切分方式必须对齐，否则缩放因子随序列位置漂移，注意力分数出现系统性偏差。可复现的做法是：KV cache 的量化粒度独立于权重块，按头维度或按固定 token 块共享缩放，且只在 decode 阶段启用，prefill 阶段保留高精度写入，避免首包延迟被 KV 反量化拖累。</p>\n<div class=\"formula\">$$M_{\\text{kv}} = 2\\cdot L\\cdot H\\cdot d_h\\cdot S\\cdot b_{\\text{kv}},\\quad \\text{saved} = 1-\\frac{b_{\\text{kv}}}{b_{\\text{ref}}}$$</div>\n<p>这里的代价是显存与带宽的权衡：KV 量化把每 token 的缓存字节数压低，长上下文场景下能容纳更大 batch，但反量化在 decode 每步都要做，块缩放元数据的读取会叠加到本就带宽受限的 decode 路径上。具体例子：分离式预填/解码部署中，prefill 节点写 KV 用 BF16，decode 节点读 KV 时按头维度做块缩放反量化，decode 的每步延迟增加了解码开销，但换来了 decode 侧能驻留更多并发序列，吞吐提升足以覆盖这部分延迟——前提是 batch 足够大，元数据开销被摊薄。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-29\">二十九 · 调度参数与批处理形态</h3>\n<p>调度参数的核心矛盾是：MXFP8 的收益随 batch 增大而增大，但流式 TTS 的 SLO 以首包延迟与实时率为约束，不允许无限堆 batch。连续批处理（continuous batching）在这里的作用不是简单地把请求攒大，而是把 chunk 级请求按到达时间拼成批，让每个 decode step 的有效 batch 尽量高，同时不阻塞首包。可复现的参数思路是：为 chunk 批量设一个最大等待窗口，窗口内到达的 chunk 合并成一次前向；窗口外的首包请求单独走低延迟路径（BF16 或 per-channel），不参与 MXFP8 批。</p>\n<ul>\n<li>批大小上限由显存预算反推：权重显存（MXFP8 + BF16 混合）+ KV cache + 激活峰值，三者之和留出余量后确定最大并发 chunk 数。</li>\n<li>调度器按层敏感度分流：敏感层请求走 BF16 路径，非敏感层请求走 MXFP8 批，两条路径共享同一套 KV 分配器。</li>\n<li>实时率约束转化为每 chunk 的截止时间，调度器在截止时间前优先填满 MXFP8 批，填不满则退化为小批并接受吞吐损失。</li>\n</ul>\n<p>代价是调度复杂度上升：两条精度路径意味着两套 kernel 启动配置与两套显存池，切换有开销；但换来的是首包延迟不被大批拖累，同时稳态吞吐靠 MXFP8 批撑住。具体例子：离线音频编码批场景下，请求形态是整段音频一次性进入，batch 天然大，调度器可以直接把所有层压到 MXFP8 批，块缩放元数据被充分摊薄，吞吐接近 INT8 水平；而流式 TTS 的 chunk 批量则需要在首包与稳态之间做路径切换。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-30\">三十 · 可复现的配置思路</h3>\n<p>把上述判断收敛成一条可复现的配置链，顺序是：先定硬件档位与拓扑，再定量化分层，再定 KV 策略，最后定调度参数。每一步都有明确的判定条件，不依赖调参直觉。</p>\n<table class=\"mini\"><thead><tr><th>决策点</th><th>判定条件</th><th>选择</th><th>代价</th></tr></thead><tbody>\n<tr><td>拓扑</td><td>线性层密集、隐藏维可被 32 整除</td><td>TP 沿隐藏维切分</td><td>块边界本卡闭合，无跨卡缩放同步</td></tr>\n<tr><td>拓扑</td><td>卷积通道数非 32 倍数</td><td>前端单卡 DP，不跨设备切通道</td><td>单卡显存压力上升</td></tr>\n<tr><td>量化</td><td>层输出偏差超阈值或为码本/输出层</td><td>BF16 或 per-channel</td><td>显存节省低于纯 MXFP8</td></tr>\n<tr><td>量化</td><td>动态范围够、块内分布均匀</td><td>MXINT8</td><td>解码路径短但精度档位低于 MXFP8</td></tr>\n<tr><td>KV</td><td>长上下文、decode 带宽受限</td><td>按头维度块缩放，prefill 写 BF16</td><td>decode 每步叠加反量化开销</td></tr>\n<tr><td>调度</td><td>首包 SLO 紧、chunk 到达稀疏</td><td>首包走低延迟路径，稳态走 MXFP8 批</td><td>两套路径切换开销</td></tr>\n</tbody></table>\n<p>这条链的验证方式是端到端跑三类负载：离线大批编码、流式 TTS chunk 批量、分离式预填/解码。每类负载记录首包延迟、稳态吞吐、显存峰值三个量，任何一项不达标就回退到上一个决策点调整。具体例子：若流式 TTS 的首包延迟超标，先检查是否把首包误送进了 MXFP8 批，再检查卷积前端是否因通道补齐引入了无效计算；若稳态吞吐不达标，先检查有效 batch 是否被调度窗口压得太小，再检查 KV 反量化是否叠加在 decode 关键路径上。</p>\n<p>最终落在一条工程判断上：MXFP8 在 Blackwell 上的部署不是“全模型开 MXFP8”，而是把块缩放放在它能被摊薄的位置——大 batch 的卷积与线性层前向——把码本与输出层留在 BF16，把首包留在低延迟路径，把 KV 量化与权重量化解耦。配置的可复现性来自判定条件而非经验值，任何一层不满足 32 元素对齐或 batch 摊薄条件，就退化为 per-channel 或 BF16，而不是硬上块缩放。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-31\">三十一 · 边界条件：这套配方在什么负载下会失效</h3>\n<p>这套配方的成立依赖两个前提：块维度可整除、元数据开销可摊薄。前者是结构性的，后者是负载性的，两者失效的方式完全不同。结构侧，编解码器卷积层的通道数并不天然对齐 32，补齐到 32 的倍数会带来无效计算与边界误差——补出来的通道既占 Tensor Core 周期，又在块内最大值统计里引入零值或填充值，使 $s_b = \\max_{j\\in b}|x_j| / \\mathrm{FP8}_{\\max}$ 的分母被真实通道主导、分子被填充位稀释，块内有效元素的量化台阶反而变粗。退化为 per-channel 量化能绕开补齐，但缩放粒度从 32 元素块退回单通道，离群值重新在通道内扩散，块级动态范围优势丢失。工程判断是：通道数规整的层走 MXFP8，不规整且通道数偏小的层直接保留 BF16，不要为了统一精度栈去补齐——补齐的收益在卷积层上通常抵不过无效计算。</p>\n<p>负载侧的失效更隐蔽。块缩放因子是每 32 元素一个字节量级的元数据，它必须与 FP8 操作数一起被搬运、被解码、在累加后统一应用。大 batch 下这部分开销被摊薄到每个 token 上可以忽略，但流式 TTS 的首包场景 batch 往往只有个位数，元数据读取与解码的相对占比抬升，MXFP8 的吞吐可能低于预期，甚至不如 BF16 路径——后者没有解码步骤，也没有块对齐约束。用代价模型写出来就是：</p>\n<div class=\"formula\">$$T_{\\text{blk}} \\approx \\frac{N}{32}\\left(t_{\\text{meta}} + t_{\\text{dec}}\\right) + \\frac{N}{B}\\, t_{\\text{mma}},\\quad \\text{收益条件}: \\frac{N}{B}\\,t_{\\text{mma}}^{\\text{FP8}} + \\frac{N}{32}t_{\\text{meta}} &lt; \\frac{N}{B}\\,t_{\\text{mma}}^{\\text{BF16}}$$</div>\n<p>其中 $N$ 为单次前向的元素数、$B$ 为 batch。右侧不含元数据项，左侧含，故存在一个临界 batch：低于它，MXFP8 的 Tensor Core 吞吐优势被 $t_{\\text{meta}}$ 吃掉。首包延迟是硬 SLO，此时应让首包走 BF16 或 per-channel 路径、稳态 chunk 走 MXFP8，而不是让整条链路统一降级。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-32\">三十二 · 敏感层清单与混合精度栈的落地判据</h3>\n<p>混合微缩放精度栈的划分不能按层类型拍脑袋，要按“缩放扰动是否改变离散决策”来判。RVQ 码本与输出层是典型的离散决策点：码本索引由最近邻搜索决定，块缩放因子带来的微小尺度扰动足以让某个候选跨过判决边界，索引偏移直接表现为音素错位或音质突变，这类误差不可用平均误差指标衡量。因此这两处保留 BF16 是硬约束，不是调优选项。其余层按敏感度在 MXFP8 与 MXINT8 间选择：MXINT8 的块内表示是定点，对激活分布接近均匀的线性层更省，但对长尾分布会截断；MXFP8 的块内指数位保留了块内动态范围，适合声学模型里方差大的激活。</p>\n<table class=\"mini\"><thead><tr><th>层类别</th><th>精度选择</th><th>判据</th><th>系统代价</th></tr></thead><tbody><tr><td>编解码器卷积（通道 32 倍数）</td><td>MXFP8</td><td>块对齐，离群值局部吸收</td><td>元数据带宽，大 batch 摊薄</td></tr><tr><td>编解码器卷积（通道不规整）</td><td>BF16 或 per-channel</td><td>补齐引入无效计算与边界误差</td><td>权重显存与带宽不压缩</td></tr><tr><td>声学模型线性层</td><td>MXFP8 / MXINT8 按敏感度</td><td>激活长尾程度</td><td>混合栈增加 kernel 分支</td></tr><tr><td>RVQ 码本、输出层</td><td>BF16</td><td>离散索引，缩放扰动不可容</td><td>这两层不享受带宽压缩</td></tr></tbody></table>\n<p>混合栈本身有代价：不同精度层在同一个 kernel 序列里切换，会打断融合、增加分支与寄存器压力，图优化阶段需要按精度段切分并分别做算子融合。并行拓扑上，MXFP8 的收益随张量并行度提升而摊薄——TP 切分后每卡的元素数 $N$ 下降，而块元数据按块数计、不随 TP 线性下降，故 TP 越大、每卡临界 batch 越高。部署时应把 MXFP8 集中在 DP 或 EP 维度扩展的副本上，而不是靠加大 TP 去追吞吐；NVLink 5 上的 all-reduce 若在 BF16 敏感层与 MXFP8 层之间混跑，还需注意通信量的精度不一致带来的额外转换。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-33\">三十三 · 显存与带宽：块缩放元数据把收益吃掉的那一段</h3>\n<p>MXFP8 的显存账不能只算权重本体。32 元素块共享一个 E8M0 缩放因子，意味着每 32 个 FP8 字节（32 B）额外挂 1 B 元数据，权重侧的名义压缩率从 FP8 的 1/2（相对 BF16）退化到约 32/33 的 FP8 有效密度，即相对 BF16 约 0.485 而非 0.5。单看比例微不足道，但编解码器与声学模型的权重分布极不均匀：卷积核、线性层、RVQ 码本、输出头混在一起，真正走 MXFP8 的只是其中一部分，元数据却要按块粒度与操作数一起驻留。工程上更痛的是对齐——块必须沿最后一维连续排布，卷积层若通道数不是 32 的倍数，要么补齐到 32 的整数倍（引入无效通道与边界误差），要么整层退化为 per-channel 量化，此时块级动态范围优势归零。因此显存规划要按“层”而非按“模型”做：把通道数规整、batch 敏感、离群值集中的层单独列账。</p>\n<p>带宽侧的关键是 MXFP8 操作数的读取形态。Tensor Core 读的是“FP8 数据 + 块缩放”两路流，缩放因子在累加完成后统一应用，因此每读 32 B 有效载荷就伴随一次元数据事务。设某层权重元素数为 $N$，则权重字节数为 $N + N/32$，相对 BF16 的 $2N$ 压缩比为：</p>\n<div class=\"formula\">$$r = \\frac{2N}{N + N/32} = \\frac{64}{33} \\approx 1.94$$</div>\n<p>也就是说理论带宽收益从 2× 掉到 1.94×，且这还没算元数据在 L2 与 SMEM 之间的额外搬运与解码指令开销。对解码阶段受 HBM 带宽约束的声学模型自回归前向，这 3% 的缺口在长序列、大 batch 下会被放大成可观测的吞吐差；而对预填阶段受算力约束的卷积前向，带宽缺口被 Tensor Core 吞吐掩盖，收益反而更完整。判断哪一层先崩，就看该层是 bandwidth-bound 还是 compute-bound。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-34\">三十四 · 通信：块缩放因子在集合通信里的放大效应</h3>\n<p>张量并行与流水并行下，MXFP8 的通信代价不是“传更少的字节”这么简单。All-Reduce 与 All-Gather 的语义要求参与方对同一份数值达成一致，而块缩放因子是逐块的局部量——若各 rank 在归约前各自持有不同的 $s_b$，归约后的结果必须重新量化并重新计算块缩放，否则数值尺度错配。工程做法通常是在通信前把 MXFP8 反量化回 BF16 做归约，或在归约后用接收侧的块统计重新定标；前者让通信量回到 BF16 水平，MXFP8 的通信收益归零，后者引入一次额外的块统计与重编码，延迟增加但带宽节省保留。</p>\n<p>以 NVL72 机架内的 NVLink 5 域为例，张量并行组内每层激活的 All-Reduce 若走 BF16，通信量与算力之比在 decode 阶段本就偏高；MXFP8 若不能在通信路径上保持块缩放一致性，就等于把压缩收益全部让给了计算侧而通信侧照旧。真正能吃到通信红利的是分离式预填/解码架构中的 KV 与激活传输：预填节点产出 MXFP8 激活并连同块缩放一起发给解码节点，接收侧按块解码后再进 Tensor Core，此时传输字节数下降约 1.94×，但接收侧多了一次元数据解析与重排。规模上去后，通信先崩的位置通常不是带宽而是“缩放一致性协议”的复杂度——rank 数越多，重定标路径越长，尾延迟越难压。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-35\">三十五 · 功耗与吞吐：小 batch 是 MXFP8 的收益悬崖</h3>\n<p>MXFP8 的吞吐收益依赖元数据开销被摊薄，而摊薄的分母是 batch 与序列长度。设单次前向的块数为 $B_{\\text{blk}}$，每块元数据解码与缩放应用的固定开销为 $c_m$，则有效吞吐可写成：</p>\n<div class=\"formula\">$$\\text{Thr} \\approx \\frac{B_{\\text{blk}} \\cdot 32}{\\alpha \\cdot B_{\\text{blk}} \\cdot 32 + c_m \\cdot B_{\\text{blk}}}$$</div>\n<p>其中 $\\alpha$ 为每元素的计算代价系数。$B_{\\text{blk}}$ 越小，$c_m$ 项占比越高，吞吐趋近于被元数据开销主导的平台上界。流式 TTS 的首包场景正是 $B_{\\text{blk}}$ 极小的极端：一个 chunk 的激活块数有限，块缩放因子的读取、解码、逐块应用无法与 Tensor Core 的 MMA 流水重叠，MXFP8 路径的端到端延迟可能高于 BF16 路径——这不是精度问题，是流水填充率问题。功耗侧同理：Tensor Core 在 MXFP8 下的能效优势需要持续的高占用率才能体现，小 batch 下 SM 占用率低、元数据解码单元空转，单位 token 的能耗反而上升。</p>\n<p>工程判断是给 MXFP8 设一个 batch 门槛：低于门槛走 BF16 或 per-tensor FP8 的快路径，高于门槛才切 MXFP8。门槛不是拍脑袋，而是用实测的 $c_m$ 与 $\\alpha$ 反解出吞吐交叉点，再按 SLO 的首包延迟预算倒推可接受的最小 chunk 批量。离线音频编码批、大 batch 声学模型前向这类 $B_{\\text{blk}}$ 充足的负载，才是 MXFP8 的主场。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-36\">三十六 · 尾延迟：块边界与补齐通道制造的抖动源</h3>\n<p>尾延迟在 MXFP8 下有两个专属来源。其一是块边界效应：序列长度或通道数不是 32 的倍数时，最后一个不完整块要么补齐（无效计算 + 边界误差），要么单独走退化路径，两条路径的延迟特征不同，混在同一 batch 里就产生长尾。其二是混合精度栈的层间切换：按层敏感度在 MXFP8 与 MXINT8 之间选择，意味着同一前向里存在多种操作数格式，Tensor Core 的格式切换与流水重排会插入气泡，batch 内请求若命中不同的层组合，尾延迟分布被拉宽。</p>\n<p>控制手段是把“规整性”前置到模型编译期：卷积通道补齐到 32 的整数倍并在权重里显式记录补齐掩码，使推理期不出现分支；对 RVQ 码本与输出层固定保留 BF16，避免块缩放扰动导致码本索引偏移——这类层一旦被误量化，合成音频会出现音素错位或音质突变，属于正确性故障而非性能问题，必须从 MXFP8 路径里硬隔离。尾延迟的容量规划应按 P99 而非均值做，因为块边界与格式切换的抖动是结构性的，不会随 batch 增大而消失，只会被平均掉。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-37\">三十七 · 规模上去以后哪里先崩：一条代价排序</h3>\n<p>把五类代价放在同一坐标下排序，规模扩大时最先崩的通常不是算力而是元数据路径。单卡内，显存与带宽的 3% 缺口是常数项，不随规模恶化；batch 增大后 $c_m$ 被摊薄，吞吐收益上升。真正随规模恶化的是通信侧的缩放一致性协议与尾延迟的规整性缺口：rank 数增加使重定标路径变长，请求异构使块边界分支概率上升。因此扩容时的第一优先级是保证“层维度可被 32 整除 + 敏感层硬隔离 BF16”，第二优先级才是把 MXFP8 铺到更多层。</p>\n<table class=\"mini\"><thead><tr><th>代价项</th><th>随规模的变化</th><th>先崩条件</th><th>工程对策</th></tr></thead><tbody><tr><td>显存（元数据 + 补齐）</td><td>常数比例，不恶化</td><td>通道不规整层占比高</td><td>编译期补齐、按层列账</td></tr><tr><td>HBM 带宽</td><td>常数 1.94× 上限</td><td>decode 阶段 bandwidth-bound 层</td><td>预填走 MXFP8、解码分层选型</td></tr><tr><td>集合通信</td><td>随 rank 数恶化</td><td>归约前需重定标</td><td>通信前反量化或接收侧重编码</td></tr><tr><td>功耗/吞吐</td><td>随 batch 改善</td><td>小 batch 首包</td><td>设 batch 门槛，低于门槛走 BF16</td></tr><tr><td>尾延迟</td><td>随请求异构恶化</td><td>块边界分支 + 格式切换</td><td>规整化前置、敏感层隔离</td></tr></tbody></table>\n<p>一个具体的工程判断：在 GB200 NVL72 这类机架级部署里，把 MXFP8 限定在“通道规整、batch 充足、非码本”的层集合上，其余层保持 BF16 或 per-channel 量化，比追求全模型 MXFP8 更能稳住 P99。混合微缩放精度栈的价值不在于覆盖率，而在于把元数据开销集中在能被摊薄的地方，把一致性风险挡在通信与码本之外。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-38\">三十八 · 规模上去以后，先崩的是元数据带宽而不是算力</h3>\n<p>把 MXFP8 放进一条流式 TTS 或离线音频编码的推理链，最先被放大的不是 Tensor Core 的算力需求，而是每 32 元素一块的缩放因子流。权重侧尚可把 E8M0 因子在加载时折叠进常量缓存，激活侧却必须在线生成：每个 32 元素块算一次 $\\max_{j\\in b}|x_j|$，转成 E8M0 指数，再随 FP8 操作数一起喂给 Tensor Core。以一层 $d_{in}\\times d_{out}$ 的线性层为例，激活张量每 token 的元数据字节数为</p>\n<div class=\"formula\">$$M_{\\text{act}} = \\frac{d_{in}}{32}\\ \\text{B/token},\\qquad \\text{相对激活字节比} = \\frac{1}{32}$$</div>\n<p>单看比例很小，但激活是每步重算的，而权重是常驻的。当 batch 从 1 涨到 64，激活元数据随 token 数线性增长，块统计与 E8M0 编码这两步从“可忽略的 epilogue”变成一条独立的访存流水：读一遍激活求块最大值，再写一遍量化结果与因子，等于把激活路径的显存流量抬到原来的 1.5 倍以上量级。此时瓶颈从 MMA 吞吐转到 SM 的 load/store 与 L2 带宽，Tensor Core 空转。工程判断很直接：激活侧 MXFP8 的收益必须用“每步激活字节数 × 步数”去折算，而不是看单层 FLOPs 峰值；编解码器卷积层通道数不规整时，补齐到 32 的倍数还会额外引入无效计算与边界误差，把这条流水进一步拉长。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-39\">三十九 · 小 batch 与尾延迟：因子解码摊不薄的那一段</h3>\n<p>块缩放因子在累加完成后统一应用，意味着每个 MMA 输出块都要等一次因子广播才能写回，这条依赖链在 batch 大时被并行 tile 掩盖，在 batch 小时直接暴露为首包延迟的固定开销。流式 TTS 的 chunk 批量往往只有个位数请求，每 chunk 几十毫秒的实时率预算里，因子读取与解码占掉的比例不可压缩。设单次解码开销为 $c_d$、每 chunk 的 MMA 数为 $n$，则摊薄后的有效开销为</p>\n<div class=\"formula\">$$\\text{overhead}_{\\text{eff}} = \\frac{c_d}{n\\cdot B},\\qquad B\\ \\text{为并发 chunk 数}$$</div>\n<p>$B$ 小到一定程度，$\\text{overhead}_{\\text{eff}}$ 会超过 BF16 路径省下的那部分计算时间，MXFP8 吞吐不升反降。尾延迟更麻烦：连续批处理里长音频请求与短请求混跑，长请求的激活块数量大、因子流长，其单步时间被拉长后会把整个 batch 的 p99 拖上去；调度器若按平均步时做容量规划，就会在尾部持续超时。可行做法是把 MXFP8 限定在离线音频编码批与流式 TTS 的中大 batch 档，超小 batch 首包路径保留 BF16 或 per-channel 量化，用混合精度栈把尾延迟钉在 SLO 内，而不是指望块缩放因子在小 batch 下自行摊薄。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-40\">四十 · 通信与功耗：压缩率换来的是另一种账</h3>\n<p>权重显存与带宽被压缩后，分离式预填/解码部署里跨节点的激活传输同样受益，但收益不是线性的。MXFP8 把激活压到 FP8 加 1/32 的因子字节，跨 NVLink 5 传输的有效载荷约为 BF16 的一半略多；然而接收端必须先还原因子再进 MMA，解码步骤落在通信关键路径上，NCCL 的 all-reduce 或 NIXL 的点对点搬运完成后还要多一次本地因子展开。规模上去后，通信时间被压缩、解码时间不变，Amdahl 意义下的加速上限由解码段决定：</p>\n<table class=\"mini\"><thead><tr><th>路径</th><th>载荷</th><th>关键路径新增</th><th>规模放大后的表现</th></tr></thead><tbody><tr><td>BF16 激活</td><td>基准</td><td>无</td><td>带宽先饱和</td></tr><tr><td>MXFP8 激活</td><td>约半</td><td>因子解码</td><td>解码段成为固定税</td></tr><tr><td>MXFP8 权重</td><td>常驻压缩</td><td>加载时折叠</td><td>显存与首载受益明显</td></tr></tbody></table>\n<p>功耗侧的逻辑类似：FP8 MMA 的能效高于 BF16，但块统计、E8M0 编码与因子广播都是额外的 SM 与访存活动，在算力未饱和的小 batch 区间，整卡功耗未必下降，反而因为流水更碎而抬高单位 token 能耗。真正的省电区间是大 batch 前向——MMA 占主导、元数据被摊薄。规模继续放大时，先崩的次序通常是：激活元数据带宽、因子解码的尾延迟、跨节点解码段，最后才是 Tensor Core 算力本身；容量规划应按这个次序设阈值，而不是按峰值 FLOPS 反推并发。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-41\">四十一 · 精度失败的三种指纹与定位顺序</h3>\n<p>MXFP8 的精度事故很少以“整体指标掉了”这种温和形态出现，它通常有三种可区分的指纹，诊断时必须按固定顺序排查，否则容易在错误的层上反复试错。第一种是<b>块边界毛刺</b>：由于每 32 元素共享一个 E8M0 缩放因子，块内若存在单个离群值，缩放因子被抬高，同块其余元素的有效位被压缩，误差上界由 <span class=\"formula\">$$\\text{err} \\le \\frac{s}{2}\\sqrt{32}$$</span> 给出——注意这个上界随块内缩放因子线性放大，因此毛刺表现为与音频帧边界或通道分组边界对齐的周期性失真，而非随机噪声。第二种是<b>码本索引偏移</b>：RVQ 码本与输出层若被误用块缩放量化，缩放因子扰动会让最近邻搜索落到相邻码字上，合成音频出现音素错位、音质突变，这类失败在波形上不可见，只能靠码本索引命中率与重构图距离来抓。第三种是<b>通道补齐边界误差</b>：卷积层通道数不是 32 的倍数时补齐零通道，补齐区参与块统计会污染缩放因子，边界通道的输出偏差随层数累积。</p>\n<p>定位顺序应为：先查码本索引命中率（最贵、最不可逆），再查逐层激活的块内最大绝对值分布（找离群块），最后查通道补齐掩码是否与块分组对齐。工程上把这三项做成推理侧的轻量旁路探针，只在采样比例上开启，避免探针本身成为吞吐瓶颈。代价是明确的：每层每块统计一次最大绝对值意味着一次额外的 reduction，在解码器卷积层上这笔开销与块缩放解码本身同量级，因此探针必须采样化，且采样率要按层敏感度分配——敏感层全采、非敏感层稀疏采。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-42\">四十二 · OOM 的真实来源：元数据、补齐与 KV 之外的第三块显存</h3>\n<p>MXFP8 的显存账不能只算权重位宽。权重按 32 元素块压到 FP8 后，每块附一个字节量级的 E8M0 缩放因子，元数据占比约为 1/32 的权重体积；这部分在小模型上可忽略，但在编解码器与声学模型叠加、且 RVQ 码本与输出层保留 BF16 的混合精度栈里，元数据与 BF16 保留层共同构成“第三块显存”，它既不随 batch 缩放，也不随序列长度缩放，却会在长音频离线编码批里把显存推到临界。更隐蔽的是通道补齐：为满足 32 整除而补齐的零通道在权重与激活上都占实存，补齐率高的层实际显存高于标称位宽推算值。</p>\n<p>诊断 OOM 时应把显存拆成四栏：BF16 保留层、MXFP8 权重加元数据、补齐冗余、激活与工作区。若 OOM 发生在批启动瞬间而非稳态，多半是补齐冗余与工作区峰值叠加；若发生在长序列中段，则是激活的块统计缓冲未复用。回滚路径上，优先把补齐率最高的卷积层退化为 per-channel 量化——这丢掉块级动态范围优势，但立刻消除补齐冗余；其次把元数据改为按需解码而非常驻，代价是每次前向多一次元数据读取，属于带宽换显存。判断依据是补齐率与元数据占比的相对大小，而不是凭经验拍板。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-43\">四十三 · 批抖动与路由不均：小 batch 下收益被抵消的量化证据</h3>\n<p>连续批处理下 MXFP8 的吞吐曲线不是单调的。块缩放因子的元数据读取与解码开销按块计，与 batch 大小基本无关，而 Tensor Core 的有效计算随 batch 增长；两者相抵的拐点就是“小 batch 下收益被抵消”的位置。用可测的量表达：设单块元数据解码代价为 <span class=\"formula\">$$c_m$$</span>，单块有效计算代价为 <span class=\"formula\">$$c_c / B$$</span>（B 为有效 batch），则 MXFP8 相对 BF16 的净收益正比于 <span class=\"formula\">$$\\frac{c_c}{B} - c_m$$</span> 的符号。流式 TTS 的首包 chunk 往往只有个位数请求，此时该式常为负，表现为首包延迟不降反升——这不是精度问题，是负载形态与格式不匹配。</p>\n<p>批抖动的另一个来源是路由不均：分离式预填/解码部署里，预填节点吃大 batch 的卷积前向，解码节点吃小 batch 的逐 token 线性层，同一套 MXFP8 精度栈在两侧的收益符号相反。监控上应分别统计预填与解码两侧的每请求块数与元数据解码占比，而不是看全局吞吐。路由不均的典型症状是解码侧 P99 抬升而预填侧吞吐正常，此时把解码侧敏感层切回 BF16 或 per-channel，比调整路由权重更直接。代价是解码侧显存回升，需与 KV cache 预算重新平衡。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-44\">四十四 · 尾延迟尖刺：块统计的同步点与补齐的边界计算</h3>\n<p>尾延迟尖刺在 MXFP8 路径上有两个结构性来源，都与“块”这个粒度绑定。其一是块统计的同步点：激活量化为 MXFP8 需要在前向中插入块内最大绝对值归约，这个归约在张量并行或流水并行下是一个跨卡同步点，一旦某张卡的块分布出现离群值，归约结果被拉高，整条流水线的下一段等待被放大，表现为与特定输入长度对齐的尖刺。其二是补齐通道的边界计算：补齐区虽然数值为零，但仍参与 Tensor Core 的 MMA 与块统计，边界 tile 的利用率下降，在尾部长音频上被放大成可观测的延迟台阶。</p>\n<p>诊断尖刺要把时间轴切成“归约等待”“MMA 有效”“MMA 无效（补齐）”三段，分别看 P99 贡献。若尖刺集中在归约等待，处理方式是预统计或把归约移到非关键路径，代价是精度上界放宽、需要重新校验码本命中率；若集中在补齐无效计算，处理方式是改量化粒度而非继续补齐。监控指标上，块内最大绝对值的分布尾部比均值更有诊断价值——均值平稳而尾部抬升，就是尖刺的前兆。回滚判据应写成“连续若干窗口内 P99 超过基线且归约等待占比上升”，而不是单次毛刺即回滚，否则会在正常的长尾输入上反复误触发。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-45\">四十五 · 监控面与回滚梯度：从混合精度栈逐级降级</h3>\n<p>监控面要覆盖四个维度，且每个维度都要能独立回滚：精度面看码本索引命中率、重构图距离、逐层块内最大绝对值尾部；显存面看四栏拆分与补齐率；吞吐面看预填/解码分离的每请求块数与元数据解码占比；延迟面看归约等待与补齐无效计算的时间占比。这四个维度共享同一批采样探针，探针本身的开销必须计入 SLO 预算，否则监控会成为新的抖动源。</p>\n<p>回滚不是二元的“开/关 MXFP8”，而是一条梯度：第一级把 RVQ 码本与输出层锁死 BF16（这两层本就不该走块缩放）；第二级把补齐率最高的卷积层退化为 per-channel；第三级把敏感线性层切 MXINT8 或 BF16；第四级整体回落到 per-tensor FP8 或 BF16 路径。每一级都对应明确的代价变化——第一级几乎无损但解决码本偏移，第二级消除补齐冗余但丢块级动态范围，第三级牺牲吞吐换稳定，第四级放弃 Blackwell 原生 MX 吞吐优势。回滚触发应绑定具体指纹而非全局指标，例如码本命中率下滑触发第一级，补齐率超阈值触发第二级。工程判断的落点是：把“层敏感度表”与“回滚梯度”做成同一份配置，精度栈的每一次降级都对应表里的一行，使失败模式与处置动作一一映射，而不是在事故现场重新推导。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-46\">四十六 · 失效边界：块缩放的三类代价与可观测信号</h3>\n<p>MXFP8 的失效不是随机噪声，而是有确定触发条件的结构性退化，可归为三条路径。第一条是<strong>通道不规整</strong>：编解码器卷积层通道数不总是 32 的倍数，补齐到 32 会引入无效计算与边界误差，退化为 per-channel 量化又丢掉块级动态范围优势，形成两难。第二条是<strong>元数据摊薄失败</strong>：每 32 元素一个 E8M0 缩放因子，意味着每读 32 个 FP8 元素就要多读一个字节并做一次解码，小 batch 流式首包场景下这部分开销无法被计算量摊薄，MXFP8 吞吐可能低于预期甚至不如 BF16 路径。第三条是<strong>敏感层误用</strong>：对 RVQ 码本与输出层施加块缩放量化，缩放因子扰动会直接导致码本索引偏移，合成音频出现音素错位或音质突变——这类错误在波形上表现为局部突变而非全局劣化，最容易被漏检。</p>\n<p>把三条路径统一到一个可观测的量上，是诊断的关键。块内量化误差上界由缩放步长决定：</p>\n<div class=\"formula\">$$\\text{err}_b \\le \\frac{s_b}{2}\\sqrt{32},\\quad s_b = \\frac{\\max_{j\\in b}|x_j|}{\\mathrm{FP8}_{\\max}}$$</div>\n<p>该式说明误差随块内最大绝对值线性增长，因此<strong>块最大值分布</strong>就是最灵敏的探针。工程上应逐层记录每块 $\\max_j|x_j|$ 的直方图：若某层出现少量块的最大值远高于其余块（离群块），说明块粒度仍不够细或该层应退化为 per-channel；若某层块最大值整体贴近 FP8 上限，说明缩放因子已饱和、有效位被压缩。配合逐层输出与 BF16 参考路径的相对误差统计，可在不中断服务的前提下定位到具体层与具体块索引，而不是笼统地\"精度掉了\"。</p>\n<p>系统侧的失败模式则表现为批抖动与尾延迟尖刺，其成因与精度问题正交。块缩放解码是逐块串行的元数据读取，当连续批处理把不同长度的 chunk 混在一个 batch 里，短 chunk 提前退出、长 chunk 继续占用 SM，MXFP8 的固定元数据开销在残余小 batch 上被放大，形成吞吐塌陷。监控上应把<strong>有效 batch 元素数</strong>与<strong>每 token 元数据字节数</strong>作为一对指标联动观察：前者下降而后者不变，即为摊薄失效的先行信号。尾延迟尖刺还需区分来源——是补齐通道引入的无效计算在特定通道数上触发，还是路由不均导致某几张卡承担了离群块密集的层。前者看 kernel 级通道对齐标志，后者看每卡块最大值分布的偏斜度。</p>\n<table class=\"mini\"><thead><tr><th>失败模式</th><th>可观测信号</th><th>回滚动作</th></tr></thead><tbody><tr><td>通道非 32 倍数</td><td>该层块最大值直方图出现边界块异常</td><td>该层退 per-channel 或 BF16</td></tr><tr><td>小 batch 摊薄失效</td><td>有效 batch 元素数降、元数据字节数不变</td><td>该请求走 BF16 路径或合并 chunk</td></tr><tr><td>码本索引偏移</td><td>RVQ 索引与参考路径不一致率上升</td><td>码本与输出层强制 BF16</td></tr></tbody></table>\n<p>回滚必须做到<strong>层粒度而非模型粒度</strong>。按层敏感度在 MXFP8 与 MXINT8 间选择的混合精度栈，本身就提供了回滚的落点：把出问题的层从 MXFP8 切到 MXINT8 或 BF16，只需替换该层的量化描述符与权重副本，不必重载整个模型，KV cache 与调度状态不受影响。代价是显存中需常驻一份敏感层的 BF16 权重，压缩收益按层占比打折；同时混合栈让 kernel 选择变复杂，每层可能落到不同 Tensor Core 路径，launch 开销与编译缓存规模上升。因此回滚策略的设计目标不是\"永不失败\"，而是把失败限制在单层、把恢复时间压到一次描述符切换的量级。</p>\n<h3 id=\"alg-mx-fp8-codec-sec-47\">四十七 · 对照维度：先分清\"缩放粒度\"与\"数据通路\"</h3>\n<p>把 MXFP8 放进同族算法里比较，最容易犯的错是按\"比特数\"排序，而不是按两个正交维度拆解：缩放粒度（per-tensor / per-channel / per-block-32 / per-group 更细）与数据通路（是否走 Blackwell 原生 MX Tensor Core 操作数、缩放因子在累加前还是累加后应用）。MXFP8 的定位是\"块级缩放 + 原生 MX 通路\"，这两个条件同时成立才有它宣称的收益。同族里 per-tensor FP8 是\"张量级缩放 + 原生 FP8 通路\"，per-channel INT8 是\"通道级缩放 + INT8 通路\"，而 MXINT8 是\"块级缩放 + INT8 数值域\"。四者的差别不在精度标签，而在离群值被吸收的粒度与元数据解码的代价结构。</p>\n<p>判断一个层该落到哪一档，用一条可算的判据：块内动态范围比 $R_b=\\max_j|x_j|/\\min_{j:|x_j|&gt;\\epsilon}|x_j|$ 与块间离散度 $\\sigma_s$。若某层 $\\sigma_s$ 大而块内 $R_b$ 小，说明离群值是\"整块整块地偏\"，per-tensor 缩放必然牺牲其余块的有效位，MXFP8 正好对症；若 $R_b$ 本身极大（块内既有近零又有尖峰），32 元素共享一个 E8M0 因子仍不够，需要退到更细粒度或保留 BF16。这条判据比\"看层名\"可靠，因为编解码器里同名卷积层在不同声学前端下的统计差异可以很大。</p>\n<div class=\"formula\">$$\\text{sel}(l)=\\begin{cases}\\text{MXFP8}, &amp; \\sigma_s \\text{ 大},\\ R_b \\text{ 温和},\\ \\dim \\bmod 32 = 0\\\\ \\text{MXINT8}, &amp; \\sigma_s \\text{ 大},\\ \\text{数值域更集中}\\\\ \\text{per-channel}, &amp; \\dim \\bmod 32 \\neq 0\\\\ \\text{BF16}, &amp; R_b \\text{ 极端或层敏感}\\end{cases}$$</div>\n<p>系统代价上，这个判据直接对应显存与带宽：MXFP8 相对 BF16 把权重位宽压到约四分之一，但每 32 元素附带一个 E8M0 因子，元数据占比约 $1/32$ 字节量级，实际压缩率略低于名义值；per-channel 量化元数据更少但动态范围优势丢失。延迟侧的关键是元数据解码是否落在关键路径——小 batch 流式首包时，解码开销无法被摊薄，这正是 MXFP8 在首包场景不宜单独依赖的原因。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-48\">四十八 · 决策表：把适用条件写成可执行的门槛</h3>\n<p>下表把同族算法的选择条件收敛成工程门槛，列的是\"满足即选\"的硬条件，而不是偏好排序。表内不写实验数字，只写结构性条件与代价方向。</p>\n<table class=\"mini\"><thead><tr><th>算法</th><th>缩放粒度</th><th>硬门槛</th><th>主要代价</th><th>典型落点</th></tr></thead><tbody>\n<tr><td>per-tensor FP8</td><td>整张量</td><td>层内无显著离群值</td><td>离群值压缩其余元素有效位</td><td>统计平稳的线性层</td></tr>\n<tr><td>per-channel INT8</td><td>通道</td><td>通道数任意</td><td>丢失块级动态范围</td><td>通道不规整卷积</td></tr>\n<tr><td>MXFP8</td><td>32 元素块</td><td>$\\dim \\bmod 32=0$ 或可补齐；batch 足以摊薄元数据</td><td>元数据读取与解码；补齐引入无效计算</td><td>大 batch 卷积与线性层</td></tr>\n<tr><td>MXINT8</td><td>32 元素块</td><td>同上，且数值域集中</td><td>同 MXFP8，数值域更窄</td><td>敏感度中等的层</td></tr>\n<tr><td>BF16</td><td>无</td><td>层敏感或 $R_b$ 极端</td><td>位宽与带宽翻倍</td><td>RVQ 码本、输出层</td></tr>\n</tbody></table>\n<p>读表时要抓住两个\"否决项\"。第一是维度否决：卷积层通道数不总是 32 的倍数，补齐会引入无效计算与边界误差，退化为 per-channel 又丢掉块级动态范围优势，此时 MXFP8 的净收益为负，应直接走 per-channel。第二是 batch 否决：块缩放因子的元数据读取与解码开销在小 batch 下无法摊薄，MXFP8 吞吐可能低于预期甚至不如 BF16 路径。两个否决项任一成立，就不要在决策表里给 MXFP8 打勾。</p>\n<p>举例：一个流式 TTS 的声学前端，卷积通道数为 24，若强行补齐到 32，补出的 8 个通道全程参与计算但不贡献信息，等于把该层算力放大约三分之一而精度不升；正确做法是该层走 per-channel INT8，把 MXFP8 留给通道数为 32 倍数的线性层与后续卷积。这就是\"同族算法怎么选\"落到具体层上的样子。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-49\">四十九 · 与 per-tensor FP8 的分界：离群值分布决定一切</h3>\n<p>per-tensor FP8 与 MXFP8 的分界不在精度指标，而在离群值的空间分布。per-tensor 用单一缩放覆盖整张量，一个极端值会把其余元素的有效位整体压低；MXFP8 每 32 元素独立缩放，局部动态范围得以保留。把这件事写成误差上界：per-tensor 下误差由全局最大值决定，MXFP8 下误差由块内最大值决定，块内误差满足 $\\text{err}\\le \\frac{s_b}{2}\\sqrt{32}$，其中 $s_b$ 随块变化。于是同一张量里，若离群值集中在少数块，MXFP8 的误差只在那几块上升，其余块保持细粒度；per-tensor 则是全张量一起退化。</p>\n<p>推理系统代价的差异体现在两处。显存侧，两者名义位宽相同，但 MXFP8 多出每 32 元素一个因子的元数据，压缩率略低；带宽侧，MXFP8 读取权重时多一次元数据流，若 batch 小则这次额外读取在总带宽中占比上升。吞吐侧，per-tensor FP8 的解码路径更短，在离群值不严重的层上反而更快。所以\"MXFP8 全面优于 per-tensor FP8\"是错的：只有在离群值局部化且 batch 足够大时，MXFP8 的精度收益才抵得过元数据开销。</p>\n<p>具体例子：声学模型的某线性层若统计显示最大值集中在少数通道，per-tensor 缩放会把其余通道压到低位深，合成音频出现细节丢失；换 MXFP8 后，离群块单独缩放，其余块恢复有效位，音质回稳。反之，若该层统计平稳、无局部尖峰，per-tensor FP8 解码更短、吞吐更高，此时选 MXFP8 是纯开销。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-50\">五十 · 与 MXINT8 的分工：数值域与敏感度分层</h3>\n<p>MXFP8 与 MXINT8 共享 32 元素块与 E8M0 缩放因子的骨架，差别在块内数值域：FP8 有指数位，能表示跨数量级的块内值；INT8 是均匀格点，在块内值分布集中时量化步长更细。选择依据是块内值的分布形态而非层的重要性标签。若块内值跨越多个数量级，FP8 的指数位避免了大值吃掉小值的有效位；若块内值集中在窄区间，INT8 的均匀格点在同一缩放因子下给出更小的绝对误差。</p>\n<p>工程上这对应一个分层策略：按层敏感度在 MXFP8 与 MXINT8 间选择，形成混合微缩放精度栈。敏感层（对量化扰动放大系数高的层）用 MXFP8 保住动态范围，中等敏感层用 MXINT8 换更细的块内步长，极敏感层与 RVQ 码本、输出层保留 BF16。代价是精度栈分层后，每层的数据通路与元数据格式不同，编译期需要按层派发不同的 MMA 变体，kernel 数量上升，首次编译与调优成本增加；运行期则因层间格式切换带来少量流水线气泡，在大 batch 下被摊薄，在小 batch 下需谨慎。</p>\n<p>伪代码思路：对每层先做一次离线统计，算出 $\\sigma_s$ 与块内分布形态，再按上表门槛派发格式，把派发结果固化为引擎的层配置。推理时不再动态判定，避免运行期分支。这条路径的代价是一次性统计与编译开销，收益是运行期无分支、格式固定，便于 Tensor Core 直接读操作数。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-51\">五十一 · 与更细粒度量化及 BF16 回退的边界</h3>\n<p>同族里还有比 32 元素更细的 group 量化（如按 16 或 8 元素分组）。粒度越细，离群值吸收越好，但元数据占比按 $1/g$ 上升，解码开销同步上升。MXFP8 选 32 是因为它同时匹配 Blackwell 原生 MX 格式的块宽与 Tensor Core 的操作数布局：块宽与硬件对齐时，缩放因子可在累加后统一应用而不打断 MMA 流水；偏离这个块宽，要么元数据解码进入关键路径，要么需要额外的重排 kernel。因此\"更细一定更好\"在 MX 通路上不成立，粒度选择首先是硬件对齐问题，其次才是精度问题。</p>\n<p>BF16 回退的边界要写死：RVQ 码本与输出层必须保留 BF16，因为块缩放因子的扰动会导致码本索引偏移，合成音频出现音素错位或音质突变。这类层的错误不是\"精度略降\"，而是离散索引跳变，误差被码本结构放大。判断某层能否离开 BF16，看它的输出是否经过离散化或索引查表：经过的，回退；不经过的，才允许进入微缩放栈。系统代价上，保留 BF16 的层位宽翻倍，但这类层通常参数量占比小，对总显存与带宽的拖累有限，换来的是索引稳定性。</p>\n<p>具体例子：输出层若被误用量化，缩放因子随块变化，同一帧在不同块边界处投影出的码本距离发生微小偏移，argmax 结果在相邻码本间抖动，听感上表现为音素边界处的突变。把这一层钉死在 BF16，其余层走 MXFP8，才是可部署的混合栈。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-52\">五十二 · 选型收口：三个否决项与一条固化路径</h3>\n<p>把同族算法的选择收口成三个否决项，任一成立即降档：维度否决（$\\dim \\bmod 32\\neq 0$ 且补齐代价高于收益）走 per-channel；batch 否决（小 batch 流式首包，元数据无法摊薄）不单独依赖 MXFP8；离散否决（输出经索引查表或离散化）回退 BF16。三个否决项之外，再按 $\\sigma_s$ 与块内分布形态在 MXFP8 与 MXINT8 间二选一。这套顺序保证选型不依赖调参试错，而是由层的统计与形状直接决定。</p>\n<p>固化路径是：离线统计每层的 $\\sigma_s$、$R_b$ 与维度余数，按上述顺序派发格式，写入引擎层配置；运行期只读配置、不判定。代价是一次性统计与按层派发带来的 kernel 数量上升与编译调优成本；收益是运行期无分支、格式与硬件对齐、元数据解码可预测。对编解码器这类层数多、形状杂的模型，固化路径比运行期动态选型更稳，因为动态判定会在首包路径上引入不可控的解码延迟。</p>\n<p>最后落在一条工程判断上：MXFP8 的收益来自\"块级缩放吸收局部离群值\"与\"原生 MX 通路\"两个条件同时成立，缺一即退。选型时先查维度余数与 batch 规模这两个硬门槛，再查离群值是否局部化，最后查输出是否离散化——顺序不能颠倒，因为前两项决定净收益正负，后一项只决定精度档位。把这三步写进层配置生成脚本，比在部署后靠精度回归去猜要可靠得多。</p>\n\n<h3 id=\"alg-mx-fp8-codec-sec-53\">五十三 · 同族取舍：MXFP8 与 per-tensor FP8、MXINT8、BF16 的分界</h3>\n<p>把 MXFP8 放进同族里看，真正的分界不在“是否 8 位”，而在缩放粒度与元数据开销的比值。per-tensor FP8 用单一缩放覆盖整张量，一个离群值就压缩其余元素的有效位；MXFP8 把粒度降到 32 元素块，代价是每块一个 E8M0 因子，量化误差上界随块尺度收缩为 <span class=\"formula\">$$\\text{err}_b \\le \\frac{s_b}{2}\\sqrt{32},\\quad s_b=\\frac{\\max_{j\\in b}|x_j|}{\\mathrm{FP8}_{\\max}}$$</span> 而 per-tensor 的误差由全张量最大值决定，块内小值元素被迫共享大尺度。MXINT8 则是另一条路：定点表示没有指数位，块内动态范围窄但解码更廉价、累加路径更规整。BF16 不参与这场比较的精度维度，它只在敏感层作为兜底。选择逻辑因此是三问：层维度能否被 32 整除、batch 能否摊薄元数据、该层是否对缩放扰动敏感。</p>\n<table class=\"mini\"><thead><tr><th>方案</th><th>适用条件</th><th>主要代价</th><th>失效点</th></tr></thead><tbody><tr><td>MXFP8</td><td>维度可被 32 整除或可补齐；大 batch 前向；卷积与线性层</td><td>每 32 元素一字节量级元数据 + 解码开销</td><td>小 batch 流式首包；通道数不规整</td></tr><tr><td>per-tensor FP8</td><td>张量内分布均匀、无强离群值</td><td>离群值压缩其余元素有效位</td><td>编解码器/声学模型动态范围不足时精度塌陷</td></tr><tr><td>MXINT8</td><td>块内分布集中、追求解码廉价</td><td>无指数位，跨块动态范围靠因子承担</td><td>块内跨度大时饱和</td></tr><tr><td>BF16</td><td>RVQ 码本、输出层、敏感层</td><td>显存与带宽翻倍于 8 位路径</td><td>作为提速主力时吞吐受限</td></tr></tbody></table>\n<p>系统代价要按 batch 摊开算。设每块元数据读取与解码耗时为 <span class=\"formula\">$$t_{\\text{meta}}$$</span>，则有效吞吐增益近似为 <span class=\"formula\">$$\\frac{T_{\\text{BF16}}}{T_{\\text{MXFP8}}} \\approx \\frac{1}{1 + t_{\\text{meta}}/t_{\\text{mma}} \\cdot (1/B)}$$</span> 其中 <span class=\"formula\">$$B$$</span> 为批内并行块数、<span class=\"formula\">$$t_{\\text{mma}}$$</span> 为单块 Tensor Core 计算时间。B 小时元数据项不可忽略，MXFP8 的吞吐可能低于预期甚至不如 BF16 路径；B 大时该项被摊薄，收益才显现。这正是流式 TTS 首包场景不宜单独依赖 MXFP8 提速的原因——首包延迟由单 chunk 决定，元数据开销无处摊销。</p>\n<p>边界条件还有两条硬约束。其一，编解码器卷积层通道数不总是 32 的倍数，补齐会引入无效计算与边界误差，退化为 per-channel 量化又丢掉块级动态范围优势，此时应按层敏感度在 MXFP8 与 MXINT8 间切换，形成混合微缩放精度栈，而不是强行统一。其二，RVQ 码本与输出层误用块缩放量化会因因子扰动导致码本索引偏移，合成音频出现音素错位或音质突变，这两处必须保留 BF16。工程判断落在一条可执行规则上：先按维度整除性与 batch 规模筛掉不适用层，再对剩余层做敏感度排序，把 MXFP8 留给大 batch 的卷积与线性前向，把 MXINT8 留给解码廉价性优先的块，把 BF16 留给码本与输出。</p>\n<table class=\"mini\" data-fig=\"alg-quick\"><caption>速查：这一页回答的五件事</caption><thead><tr><th>项</th><th>内容</th></tr></thead><tbody><tr><td>年份 · 方向</td><td>2023 · 流式投机解码与多 token 预测</td></tr><tr><td>解决什么</td><td>编解码器与声学模型在 FP8 下动态范围不足，整张量缩放会因局部离群值牺牲精度，难以在 Blackwell 上安全使用…</td></tr><tr><td>一句话机制</td><td>采用 OCP MX（microscaling）数据格式，把权重/激活按 32 元素块共享一个 E8M0 缩放因子，块内…</td></tr><tr><td>代价与失效</td><td>块缩放因子带来额外元数据与解码开销，小 batch 下收益被抵消；编解码器卷积层通道数不总是 32 的倍数，需补齐或退化为 per-cha…</td></tr><tr><td>后继</td><td>自回归码本 LM 投机解码</td></tr></tbody></table>\n<p class=\"paper-line\">本页对应：algorithms/alg-mx-fp8-codec · 共 8 个片段</p>\n";break;}}})();
